window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[272]={"id":"272","numero":272,"titre":"Ulcère gastroduodénal - gastrite","objectifs":[{"id":"272-1","rang":"A","rubrique":"Définition","titre":"Connaître les définitions d'un ulcère gastrique ou duodénal","contenu":"<div class=\"notion-course\"><p>L'<strong>ulcère gastroduodénal</strong> (<span>UGD</span>) résulte d'un <span>déséquilibre entre <span class=\"nc-gray_bg\">l'agression chlorhydropeptique</span> et les <span class=\"nc-gray_bg\">mécanismes de défense</span></span> de la <span class=\"nc-purple nc-bold\">muqueuse</span> (barrière <span class=\"nc-purple nc-bold\">muqueuse</span>), en <strong>un point précis</strong> de la paroi.</p>\n      <p>La <strong>barrière muqueuse</strong> de défense comporte <strong>trois lignes</strong> :</p>\n      <ul>\n        <li><span>Pré-épithéliale</span> : <span class=\"nc-green_bg\">mucus</span> (barrière mécanique), sécrétion de <span class=\"nc-pink nc-bold\">phospholipides</span> et de <span>bicarbonates</span> (tamponnement)</li>\n        <li><span>Épithéliale</span> : <span class=\"nc-green_bg\">cellules de surface</span> assurant le <span class=\"nc-green_bg\">renouvellement cellulaire</span></li>\n        <li><span>Sous-épithéliale</span> : <span class=\"nc-pink nc-bold\">flux sanguin muqueux</span> (vascularisation de la <span class=\"nc-purple nc-bold\">muqueuse</span>)</li>\n      </ul>\n      <p><span>Érosion</span>, ulcération et ulcère se distinguent par la <strong>profondeur</strong> de la perte de substance :</p>\n      <table>\n        <thead><tr><th><span>Lésion</span></th><th>Profondeur atteinte</th></tr></thead>\n        <tbody>\n          <tr><td><span>Érosion</span></td><td>Limitée à la <span>muqueuse</span></td></tr>\n          <tr><td><span>Ulcération</span></td><td>Limitée à la <span><span class=\"nc-purple nc-bold\">sous-muqueuse</span></span></td></tr>\n          <tr><td>Ulcère</td><td><span class=\"nc-red nc-bold\">Perte de substance de la paroi gastrique ou duodénale</span> atteignant la <span><span class=\"nc-red nc-bold\">musculeuse</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong><span>érosion</span>, ulcération et ulcère ne sont pas synonymes : seule la <span>profondeur atteinte</span> <span>les</span> discrimine. Le terme « ulcère » impose une atteinte de la <span><span class=\"nc-red nc-bold\">musculeuse</span></span>.</div>\n      <p><strong>Ulcère chronique <span>vs</span> aigu</strong> — l'ulcère chronique se distingue de l'ulcère aigu par l'existence d'un <span>socle scléro-inflammatoire dans la <span class=\"nc-red nc-bold\">musculeuse</span></span>, contenant des <strong>hyperplasies nerveuses</strong> et des lésions <span>d'endartérite</span>.</p>\n      <p><strong>Localisations préférentielles :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Ulcère duodénal</span></span> : en plein <span class=\"nc-red nc-bold\">bulbe</span> ou à la <span class=\"nc-red nc-bold\">pointe du bulbe</span> (D1)</li>\n        <li><span>Ulcère gastrique</span> : <span class=\"nc-red nc-bold\">antre</span> et petite courbure</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/gastritis","label":"Radiopaedia : Gastritis"},{"href":"https://radiopaedia.org/articles/peptic-ulcer-disease","label":"Radiopaedia : Peptic ulcer disease"}]},{"id":"272-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l'ulcère gastrique ou duodénal","contenu":"<div class=\"notion-course\"><p>L'<span>incidence</span> de l'<span>UGD</span> est en <strong>régression</strong> dans <span>les</span> pays développés, parallèlement au <span class=\"nc-green_bg\">recul de l'infection gastrique à </span><span><span class=\"nc-green_bg\">H. pylori</span></span>.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><span>Incidence</span></td><td>Pays développés <span>1 à 2 / 1000 / an</span> ; France <span>≈ 90 000 cas/an</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance <span class=\"nc-pink_bg\">masculine</span> <span><span class=\"nc-pink nc-bold\">2 H / 1 F</span></span> (LISA) ; l'ancien référentiel ne retrouvait cette prédominance que pour l'<strong><span class=\"nc-red nc-bold\">ulcère duodénal</span></strong></td></tr>\n          <tr><td>Âge</td><td><span class=\"nc-pink_bg\">Avant </span><span><span class=\"nc-pink_bg\">55 ans</span></span>, l'<span class=\"nc-red nc-bold\">ulcère duodénal</span> est <span>3 à 4×</span> plus fréquent que l'ulcère gastrique</td></tr>\n          <tr><td><span>Terrain</span></td><td>Patients avec <span>comorbidités</span> cardiovasculaire, rénale, hépatique ou pancréatique ; <span>les</span> ulcères du <span>sujet âgé</span> sont volontiers <span class=\"nc-red nc-bold\">compliqués</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Mortalité</span></strong> — le taux de mortalité des complications ulcéreuses (hémorragie, <span>comorbidités</span> associées) est de <span>2 à 10 %</span>. Un <span>tiers</span> des <span><span class=\"nc-orange_bg\">UGD</span></span><span class=\"nc-orange_bg\"> compliqués</span> est attribuable aux <span><span class=\"nc-pink_bg\">AINS</span></span> ou à l'<span><span class=\"nc-pink nc-bold\">aspirine</span> à faible dose</span>.</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":0},{"id":"272-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme des ulcères hémorragiques","contenu":"<div class=\"notion-course\"><p>L'hémorragie résulte de l'<span><span class=\"nc-yellow_bg\">ulcération des vaisseaux de la paroi gastroduodénale</span></span><span class=\"nc-yellow_bg\">.</span> En cas d'hémorragie <span>sévère</span>, il s'agit le plus souvent de l'<span>érosion</span> d'une artère, dont le siège dépend de la localisation de l'ulcère :</p>\n      <table>\n        <thead><tr><th>Siège de l'ulcère</th><th>Artère érodée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Face postérieure du bulbe duodénal</span></td><td><span><span class=\"nc-pink nc-bold\">Artère gastro-duodénale</span></span></td></tr>\n          <tr><td><span class=\"nc-red_bg\">Petite courbure gastrique</span></td><td><span><span class=\"nc-pink nc-bold\">Artère gastrique gauche</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier — <span>ulcération</span> de Dieulafoy :</strong> <span>ulcération <span class=\"nc-purple nc-bold\">muqueuse</span> en regard d'une artère <span class=\"nc-purple nc-bold\">sous-muqueuse</span> volumineuse</span>. Le diagnostic est difficile car l'artère n'est pas toujours apparente et le <span>saignement abondant</span> gêne le geste d'hémostase.</p>\n      <p><strong><span>Classification</span> de Forrest</strong> <span>(Rang B)</span> — décrit l'aspect endoscopique de l'<span class=\"nc-red nc-bold\">ulcère </span><span><span class=\"nc-red nc-bold\">hémorragique</span></span> ; elle est <strong>corrélée au risque de récidive hémorragique</strong> :</p>\n      <table>\n        <thead><tr><th><span>Stade</span></th><th>Aspect endoscopique</th></tr></thead>\n        <tbody>\n          <tr><td>I a</td><td><span>Hémorragie en jet</span></td></tr>\n          <tr><td>I b</td><td>Suintement diffus</td></tr>\n          <tr><td>II a</td><td><span class=\"nc-red nc-bold\">Vaisseau visible</span>, non <span>hémorragique</span></td></tr>\n          <tr><td>II b</td><td><span class=\"nc-red nc-bold\">Caillot adhérent</span></td></tr>\n          <tr><td>II c</td><td>Taches p<span>igm</span>entées</td></tr>\n          <tr><td>III</td><td>Cratère à fond propre</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — <span class=\"nc-red_bg\">Hémorragie digestive</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":3},{"id":"272-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisants des formes compliquées des ulcères gastrique ou duodénal","contenu":"<div class=\"notion-course\"><p><strong><span>Facteurs de risque</span> des ulcères <span class=\"nc-red nc-bold\">compliqués</span></strong> — ils prédisposent à l'hémorragie et à la perforation :</p>\n      <ul>\n        <li><span>Âge &gt; 65 ans</span></li>\n        <li><span><span class=\"nc-orange nc-bold\">ATCD d'UGD</span> compliqué</span></li>\n        <li><span><span class=\"nc-brown_bg\">AINS</span></span> ou <span><span class=\"nc-brown_bg\">aspirine</span></span>, particulièrement en cas <span class=\"nc-brown_bg\">d'</span><span><span class=\"nc-brown_bg\">infection à H. pylori</span></span> associée</li>\n        <li><span class=\"nc-brown_bg\">Prise d'</span><span><span class=\"nc-brown_bg\">anticoagulant</span></span></li>\n      </ul>\n      <p><strong><span><span class=\"nc-pink_bg\">AINS</span></span> et <span>aspirine</span></strong> — l'<span>inhibition de la COX-1</span> (qui produit <span>les</span> prostaglandines gastroduodénales) favorise les <span>UGD</span> (plutôt <strong>gastriques</strong>) et leurs complications :</p>\n      <ul>\n        <li><span>AINS</span> : risque relatif <span>≈ 4</span></li>\n        <li><span><span class=\"nc-pink nc-bold\">Aspirine</span></span> : risque relatif <span>≈ 1,5</span> ; à dose anti-agrégante, elle ajoute une <span><span class=\"nc-red nc-bold\">gastrotoxicité directe</span></span> et expose au <span>risque hémorragique</span></li>\n        <li><span>Coxibs</span> (anti-COX-2 préservant la COX-1) : réduisent le risque de complications de <span>≈ 50 %</span> <span class=\"nc-red_bg\">sans le supprimer</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">Les <span class=\"nc-orange nc-bold\">corticoïdes</span> ne justifient pas à eux seuls une gastroprotection <span class=\"nc-red nc-bold\">systématique</span> ; le risque digestif dépend du terrain et augmente notamment avec les <span class=\"nc-brown_bg\">AINS</span>.</div>\n      <p><strong><span>Syndrome de <span class=\"nc-red nc-bold\">Zollinger</span></span><span class=\"nc-red nc-bold\">-Ellison</span></strong> <span>(rare)</span> — hypersécrétion acide liée à une <span>hypergastrinémie tumorale</span> (<span class=\"nc-yellow_bg\">gastrinome</span>, tumeur neuro-endocrine pancréatico-duodénale, <span>maligne dans 50-60 %</span>) ; <span>sporadique dans 75 %</span> des cas, ou associé à une <span>NEM1</span>. Tableau : ulcères <span><span class=\"nc-red nc-bold\">multiples</span>, <span class=\"nc-red nc-bold\">récidivants</span>, souvent <span class=\"nc-red nc-bold\">compliqués</span></span> + <span><span class=\"nc-red_bg\">diarrhée chronique</span> <span class=\"nc-blue nc-bold\">sécrétoire</span></span> améliorée sous <span><span class=\"nc-yellow_bg nc-bold\">IPP</span></span>.</p>\n      <p><strong>Autres facteurs d'agression</strong> (à rechercher devant un ulcère non lié à HP ni aux <span><span class=\"nc-brown_bg nc-bold\">AINS</span></span>) :</p>\n      <ul>\n        <li><span>Tabac</span></li>\n        <li><span><span class=\"nc-orange_bg\">Maladie de Crohn</span></span>, <span><span class=\"nc-orange_bg\">vascularites</span></span></li>\n        <li>Infections chez l'immunodéprimé : <span><span class=\"nc-purple_bg nc-bold\">tuberculose</span></span>, <span><span class=\"nc-purple_bg nc-bold\">CMV</span></span></li>\n        <li><span><span class=\"nc-orange_bg\">Stress pathologique intense</span></span> : <span>réanimation</span>, grand brûlé</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pièges pertinents — </strong>ne sont <span>PAS</span> des <span>facteurs de risque</span> d'<span><span class=\"nc-blue_bg\">UGD</span></span> : l'<span>alcool</span>, le <span>régime alimentaire</span>, le <span>stress psychologique</span>. L'<span>alcool</span> est cependant pourvoyeur de gastropathie chimique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span> · 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":0},{"id":"272-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l'importance d'Helicobacter pylori (HP) dans la récidive ulcéreuse","contenu":"<div class=\"notion-course\"><p><strong><span><span class=\"nc-red_bg\">Helicobacter pylori</span></span></strong> — <span>bacille à Gram négatif flagellé, spiralé</span>, doté d'une <span><span class=\"nc-pink nc-bold\">activité</span> <span class=\"nc-pink nc-bold\">uréasique</span></span> qui lui permet de résister à l'acidité gastrique ; il colonise la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique.</p>\n      <p><strong>Rôle dans la récidive ulcéreuse</strong> — l'<span>éradication d'HP</span> est ce qui prévient la récidive de l'ulcère. Un <span>UGD</span> associé à HP et <span>non éradiqué récidive de façon quasi constante</span>.</p>\n      <p><strong>Profils sécréteurs et complications</strong> de la <span><span class=\"nc-orange_bg\">gastrite</span></span><span class=\"nc-orange_bg\"> chronique</span> à HP :</p>\n      <table>\n        <thead><tr><th>Profil</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td>Hypersécréteur</td><td><span>Gastrite</span> <span>antrale peu atrophiante</span> → <span><span class=\"nc-blue nc-bold\">hyperchlorhydrie</span></span> → <span><span class=\"nc-red nc-bold\">ulcère duodénal</span></span> (≈ <span>10 %</span>)</td></tr>\n          <tr><td>Hyposécréteur</td><td><span><span class=\"nc-red\">Atrophie</span></span> de la <span class=\"nc-purple nc-bold\">muqueuse</span> → <span><span class=\"nc-blue nc-bold\">achlorhydrie</span></span> → <span><span class=\"nc-red nc-bold\">ulcère gastrique</span></span> (≈ <span>3 %</span>) ; séquence <span class=\"nc-red nc-bold\">métaplasie intestinale</span> (<span>40 %</span>) → <span class=\"nc-red\">dysplasie</span> (<span>8 %</span>) → <span><span class=\"nc-red nc-bold\">adénocarcinome gastrique</span></span> (<span>1-3 %</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans le contexte de l'infection à HP, à <span class=\"nc-blue nc-bold\">prédominance antrale</span>, <span>les</span> <span>ulcères duodénaux sont 3 à 4× plus fréquents</span> que les ulcères gastriques.</p>\n      <div class=\"callout callout-info\"><strong>Pierre angulaire — </strong>l'<span>éradication d'<span class=\"nc-pink_bg\">H. pylori</span></span> est la mesure de prévention de la récidive ulcéreuse.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":0},{"id":"272-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","contenu":"<div class=\"notion-course\"><p>Le diagnostic d'ulcère est <strong>évoqué</strong> sur la sémiologie douloureuse, mais n'est jamais affirmé sur <span>les</span> seuls symptômes.</p>\n      <p><strong><span><span class=\"nc-blue_bg\">Syndrome ulcéreux</span></span> typique</strong> — <span><span class=\"nc-yellow_bg\">douleur</span> <span class=\"nc-yellow_bg nc-bold\">épigastrique</span></span> <span class=\"nc-yellow_bg\">à type de</span> <span><span class=\"nc-yellow_bg nc-bold\">crampe</span></span>, de <span><span class=\"nc-yellow_bg nc-bold\">torsion</span></span> <span class=\"nc-yellow_bg\">ou de</span> <span><span class=\"nc-yellow_bg nc-bold\">faim douloureuse</span></span> :</p>\n      <ul>\n        <li><span>Sans irradiation</span></li>\n        <li><span><span class=\"nc-green_bg\">Calmée par la prise d'aliments</span></span>, d'anti-acides et de pansements gastriques</li>\n        <li><strong>Double périodicité :</strong> dans la journée, <span class=\"nc-yellow_bg\">douleur</span> <span><span class=\"nc-red nc-bold\">post-prandiale tardive</span></span> (<span>1 à 3 h</span> après <span>les</span> repas) ; dans l'année, <span class=\"nc-red_bg\">poussées</span> de quelques <span><span class=\"nc-pink nc-bold\">semaines</span></span> séparées par des intervalles asymptomatiques de quelques <span><span class=\"nc-pink nc-bold\">mois</span> à <span class=\"nc-pink nc-bold\">années</span></span></li>\n      </ul>\n      <p><strong>Syndrome douloureux atypique :</strong></p>\n      <ul>\n        <li>Localisation variable : <span><span class=\"nc-blue_bg\">hypochondre</span> <span class=\"nc-blue_bg nc-bold\">droit</span> ou <span class=\"nc-blue_bg nc-bold\">gauche</span></span>, <span><span class=\"nc-blue_bg\">irradiation</span></span> <span><span class=\"nc-blue_bg nc-bold\">dorsale</span> ou strictement postérieure</span></li>\n        <li>Intensité variable : forme hyperalgique pseudo-chirurgicale, ou au contraire simple gêne frustre</li>\n        <li><span>Absence de périodicité</span>, <span class=\"nc-yellow_bg\">douleur</span> <span>non rythmée par l'alimentation</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong>le syndrome douloureux <span>atypique est plus <span class=\"nc-red nc-bold\">fréquent</span></span> que la forme typique.</div>\n      <p><strong>Examen clinique</strong> — <span><span class=\"nc-green nc-bold\">normal</span></span> <span class=\"nc-brown_bg\">en l'absence de complication</span>.</p>\n      <p><strong>Autres circonstances de découverte :</strong></p>\n      <ul>\n        <li><span class=\"nc-green_bg\">Forme </span><span><span class=\"nc-green_bg\">asymptomatique</span> / <span class=\"nc-green_bg\">fortuite</span></span> (<span>UGD</span> révélé par une <span>endoscopie</span> faite pour une autre raison) : jusqu'à <span>2/3</span> des cas selon certaines études</li>\n        <li>Complication inaugurale : <span><span class=\"nc-red nc-bold\">hémorragie</span> ou <span class=\"nc-red nc-bold\">perforation</span></span> d'emblée, sans signe d'alarme ; <span><span class=\"nc-red nc-bold\">sténose</span></span> révélée par des <span><span class=\"nc-orange nc-bold\">vomissements</span></span><span class=\"nc-orange nc-bold\"> post-prandiaux</span></li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":2},{"id":"272-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","contenu":"<div class=\"notion-course\"><div class=\"callout callout-info\"><strong><span><span class=\"nc-blue_bg\">EOGD</span></span> — </strong>l'<span><span class=\"nc-blue_bg\">endoscopie</span></span><span class=\"nc-blue_bg\"> digestive haute</span> <strong>affirme le diagnostic</strong> d'ulcère, qui ne peut pas reposer sur <span>les</span> seuls symptômes. Elle élimine les diagnostics différentiels (<span class=\"nc-red nc-bold\">cancer</span> +++ si <span class=\"nc-red nc-bold\">ulcère gastrique</span>) et permet les <span class=\"nc-blue_bg\">biopsies</span>.</div>\n      <p><strong>Indications de l'<span>EOGD</span></strong> devant une douleur ulcéreuse (identiques au <span>RGO</span>) :</p>\n      <ul>\n        <li><span>Âge &gt; 50 ans</span></li>\n        <li>OU présence de <span><span class=\"nc-red nc-bold\">signes d'alarme</span></span> : <span><span class=\"nc-red_bg\">dysphagie</span></span>, <span><span class=\"nc-red_bg\">amaigrissement</span></span>, <span class=\"nc-red_bg\">hémorragie digestive</span>, <span class=\"nc-red_bg\">anémie</span></li>\n        <li>OU inefficacité du traitement symptomatique de 1re intention</li>\n      </ul>\n      <p><strong>Modalités</strong> — <span class=\"nc-green_bg\">anesthésie </span><span><span class=\"nc-green_bg\">locale pharyngée</span></span> ou générale (l'<span class=\"nc-green_bg\">anesthésie générale</span> n'est <span>pas nécessaire</span>) ; morbi-<span>mortalité</span> faible.</p>\n      <p><strong>Aspect endoscopique de l'ulcère</strong> — perte de substance profonde « <span><span class=\"nc-red nc-bold\">creusante</span></span> », <span class=\"nc-brown_bg\">fond </span><span><span class=\"nc-brown_bg\">pseudo-membraneux</span> blanchâtre</span> parfois <span class=\"nc-red nc-bold\">nécrotique</span>, <span>lésion</span> <span class=\"nc-brown_bg\">ronde</span> ou <span class=\"nc-brown_bg\">ovalaire</span> à <span class=\"nc-brown_bg\">bords réguliers</span>, surélevés et érythémateux.</p>\n      <div class=\"callout callout-warn\"><strong>Piège — </strong>un <span><span class=\"nc-red nc-bold\">ulcère duodénal</span> post-bulbaire</span> (très rare) doit faire évoquer un <span>syndrome de <span class=\"nc-red nc-bold\">Zollinger-Ellison</span></span> ou une <span>MICI</span> (<span class=\"nc-red_bg\">Crohn</span>, <span><span class=\"nc-red_bg\">vascularite</span></span>).</div>\n      <p><strong>Conduite biopsique selon le siège :</strong></p>\n      <table>\n        <thead><tr><th>Siège</th><th>Biopsies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red nc-bold\">Ulcère duodénal</span></td><td><span>Pas de biopsie de la lésion duodénale</span> ; <span class=\"nc-yellow_bg\">biopsies gastriques (antre, angle, fundus)</span> pour la <span><span class=\"nc-yellow_bg\">gastrite</span></span> à HP ; pas de contrôle endoscopique si patient <span class=\"nc-green_bg\">asymptomatique</span>, sauf <span class=\"nc-orange_bg nc-bold\">UD compliqué</span></td></tr>\n          <tr><td>Ulcère <span class=\"nc-pink_bg\">gastrique</span></td><td>Biopsies <span class=\"nc-yellow_bg\">gastriques</span> HP + <span>6 à 12 biopsies des berges</span> de <span class=\"nc-pink nc-bold\">l'ulcère</span>, recherchant un <span><span class=\"nc-red nc-bold\">adénocarcinome</span></span> voire un <span><span class=\"nc-red nc-bold\">lymphome</span></span> ; <span>fibroscopie de contrôle</span> après traitement (<span class=\"nc-yellow nc-bold\">zone cicatricielle</span> + recherche d'HP)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"nc-red nc-bold\">Systématique</span> — </strong>la <span>recherche d'<span class=\"nc-pink_bg\">H. pylori</span></span> est <span class=\"nc-red nc-bold\">systématique</span> devant tout <span><span class=\"nc-blue_bg\">UGD</span></span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 271 — <span>RGO</span> - hernie hiatale · 303 — Tumeur estomac</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-8","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","contenu":"<div class=\"notion-course\"><ul><li>L’endoscopie précise siège, taille et aspect de l’ulcère ; un ulcère gastrique doit faire exclure une tumeur par <span class=\"nc-blue nc-bold\">biopsies</span> adaptées et contrôle de <span class=\"nc-green_bg nc-bold\">cicatrisation</span>. Un aspect macroscopique rassurant ne suffit pas.</li><li>Rechercher H. pylori par tests adaptés : biopsies pour histologie et recherche de la bactérie/résistance si endoscopie indiquée ; tests non invasifs dans les situations appropriées.</li><li>Le saignement, les antibiotiques et les IPP peuvent diminuer la sensibilité des tests : un résultat négatif pendant l’épisode aigu peut devoir être contrôlé. L’hémorragie n’interdit pas par principe toute biopsie ; décision selon sécurité du geste.</li><li>La sérologie ne prouve pas une infection <span class=\"nc-red nc-bold\">active</span> après <span class=\"nc-yellow_bg\">traitement</span> et ne sert pas à contrôler l’éradication. Pour le contrôle, privilégier le test respiratoire à l’urée selon les délais d’arrêt des traitements.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":3},{"id":"272-9","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","contenu":"<div class=\"notion-course\"><div class=\"callout callout-warn\"><strong><span class=\"nc-brown_bg nc-bold\">Pas de parallélisme anatomo-clinique</span> — </strong><span class=\"nc-brown_bg\">il n'existe</span> <span>aucun critère de gravité de la douleur ulcéreuse</span> elle-même ; l'intensité de la douleur ne préjuge pas de la gravité.</div>\n      <p>On recherche <span>les</span> <strong>signes associés à une complication</strong> :</p>\n      <table>\n        <thead><tr><th>Complication évoquée</th><th>Signes à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red nc-bold\">Perforation</span></td><td><span>Défense</span> ou <span><span class=\"nc-orange nc-bold\">contracture abdominale</span></span></td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Cancer</span></td><td><span><span class=\"nc-red_bg\">Amaigrissement</span></span>, <span>adénopathie sus-claviculaire</span> (ganglion de Troisier)</td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Hémorragie</span></td><td><span>Chute tensionnelle</span>, <span>tachycardie</span>, <span><span class=\"nc-purple_bg\">hématémèse</span> / <span class=\"nc-purple_bg\">méléna</span></span>, sang au toucher rectal</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-10","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principales complications de l'ulcère","contenu":"<div class=\"notion-course\"><p>L'<span>UGD</span> peut se compliquer de quatre façons :</p>\n      <table>\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red_bg\">Hémorragie digestive</span></span></td><td>La <strong>plus fréquente</strong>, parfois inaugurale ; <span>30-40 %</span> des hémorragies digestives hautes ; <span>mortalité</span> <span>≈ 10 %</span></td></tr>\n          <tr><td>Perforation</td><td>Moins fréquente que l'hémorragie ; favorisée par <span>les</span> <span>AINS</span></td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Sténose</span></td><td><span>Exceptionnelle</span> ; complique <span>les</span> <span class=\"nc-orange_bg\">ulcères</span> <span class=\"nc-orange_bg nc-bold\">bulbaires</span> et <span class=\"nc-orange_bg nc-bold\">pré-pyloriques</span> ; <span><span class=\"nc-blue_bg\">vomissements post-prandiaux</span> <span class=\"nc-red nc-bold\">tardifs</span></span> ; risque d'<span><span class=\"nc-orange nc-bold\">alcalose métabolique</span> hypochlorémique hypokaliémique</span></td></tr>\n          <tr><td>Dégénérescence</td><td><span>Ulcère gastrique uniquement</span> — l'<span class=\"nc-red nc-bold\">ulcère duodénal</span> ne dégénère jamais</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — <span class=\"nc-red_bg\">Hémorragie digestive</span> · 357 — <span>Péritonite</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la stratégie à adopter devant une hématémèse","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-purple_bg\">Hématémèse</span>, <span class=\"nc-purple_bg\">méléna</span> ou rectorragie abondante : évaluer immédiatement circulation, conscience et perfusion ; une Hb initiale normale n’exclut pas une <span class=\"nc-red nc-bold\">hémorragie</span> grave. Voies veineuses, bilan transfusionnel et <span class=\"nc-red nc-bold\">réanimation</span> adaptée.</li><li>Transfusion généralement restrictive, modulée par saignement actif et terrain cardiovasculaire. Réévaluer anticoagulants et antiagrégants selon gravité et risque thrombotique ; pas d’arrêt ou de neutralisation indifférencié.</li><li>Endoscopie après réanimation initiale, généralement dans les 24 <span class=\"nc-pink nc-bold\">heures</span> pour une hémorragie haute non variqueuse. Hémostase des saignements actifs et vaisseaux visibles ; adrénaline jamais utilisée seule comme <span class=\"nc-yellow_bg\">traitement</span> définitif.</li><li><span class=\"nc-yellow_bg nc-bold\">IPP</span> après hémostase à haut risque, <span class=\"nc-yellow_bg\">traitement</span> de <span class=\"nc-pink_bg\">H. pylori</span> et contrôle d’éradication. Récidive : nouvelle endoscopie, puis embolisation ou chirurgie selon échec et disponibilité. Voir item 355 pour la stratégie complète.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-12","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les mesures à mettre en œuvre dans les formes perforées","contenu":"<div class=\"notion-course\"><p><strong>Perforation en péritoine libre = <span>péritonite</span> :</strong></p>\n      <ul>\n        <li><span><span class=\"nc-yellow_bg\">Douleur</span> <span class=\"nc-yellow_bg nc-bold\">épigastrique</span> en coup de poignard</span>, à début <span>brutal</span> (ce qui la distingue de la <span>pancréatite aiguë</span>), diffusant ensuite à tout l'abdomen</li>\n        <li><span><span class=\"nc-orange nc-bold\">Contracture abdominale</span></span>, Douglas douloureux au toucher rectal, <span class=\"nc-red_bg\">signes de </span><span><span class=\"nc-red_bg\">choc</span></span></li>\n        <li><span>Tympanisme et disparition de la matité préhépatique</span> = <span class=\"nc-red nc-bold\">pneumopéritoine</span> (signe quasi-pathognomonique)</li>\n      </ul>\n      <p><strong>Signes négatifs</strong> — <span><span class=\"nc-brown_bg\">pas de fièvre</span></span> et <span><span class=\"nc-brown_bg\">pas d'hyperleucocytose</span></span> durant <span>les</span> premières <span class=\"nc-pink nc-bold\">heures</span> (<span>péritonite</span> chimique).</p>\n      <div class=\"callout callout-danger\"><strong><span>Urgence</span> — </strong><span><span class=\"nc-blue nc-bold\">TDM</span> abdomino-pelvienne injectée en 1re intention</span> (<span class=\"nc-red nc-bold\">pneumopéritoine</span> + <span>réaction inflammatoire</span> antro-pyloro-bulbaire). L'<span><span class=\"nc-blue_bg\">endoscopie</span> est formellement contre-indiquée</span>. Prise en charge d'une <span>péritonite</span> secondaire : urgence chirurgicale + <span>antibiothérapie</span> probabiliste.</div>\n      <p><strong>Facteurs favorisants</strong> — <span>les</span> <span><span class=\"nc-pink_bg\">AINS</span></span> favorisent la <span class=\"nc-red nc-bold\">perforation</span> ; les <span><span class=\"nc-pink_bg\">corticoïdes</span></span> ne la favorisent pas mais <span>retardent le diagnostic</span> en atténuant les signes cliniques.</p>\n      <p><strong>Ulcère perforé-bouché</strong> (<span class=\"nc-red nc-bold\">perforation</span> au <span>contact</span> du <span class=\"nc-purple_bg\">pancréas</span>) — <span>régression de la douleur initiale</span>, <span>pas de <span class=\"nc-red nc-bold\">pneumopéritoine</span></span> (possible rétro-<span class=\"nc-red nc-bold\">pneumopéritoine</span>) ; méthode de Taylor (<span class=\"nc-pink_bg\">SNG en aspiration</span> + <span><span class=\"nc-pink_bg\">IPP</span></span> + <span>antibiotiques</span>) possible en l'absence de <span>signe de gravité</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span>Péritonite</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":3},{"id":"272-13","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l'examen de première intention devant une contracture abdominale","contenu":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-orange nc-bold\">contracture abdominale</span></span> faisant suspecter une <span class=\"nc-red nc-bold\">perforation</span> d'ulcère :</p>\n      <div class=\"callout callout-danger\"><strong>Examen de 1re intention — </strong><span>TDM abdomino-pelvienne injectée</span> : elle recherche un <span><span class=\"nc-red nc-bold\">pneumopéritoine</span></span> et une <span>réaction inflammatoire</span> de la région antro-pyloro-bulbaire. L'<span>endoscopie est contre-indiquée</span> de façon absolue en cas de <span class=\"nc-red nc-bold\">perforation</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span>Péritonite</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-14","rang":"B","rubrique":"Suivi et / ou pronostic","titre":"Connaître le risque dégénérescence des ulcères selon leur localisation","contenu":"<div class=\"notion-course\"><p>Le <strong>risque de dégénérescence</strong> dépend strictement de la localisation de l'ulcère :</p>\n      <table>\n        <thead><tr><th>Localisation</th><th>Risque de cancérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red nc-bold\">Ulcère duodénal</span></td><td>L'<span class=\"nc-red nc-bold\">ulcère duodénal</span> <span>n'est jamais un cancer et ne se cancérise jamais</span></td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Ulcère gastrique</span></td><td>L'UG et l'<span><span class=\"nc-red nc-bold\">adénocarcinome gastrique</span></span> surviennent tous deux <span class=\"nc-red nc-bold\">sur une </span><span><span class=\"nc-red nc-bold\">muqueuse atrophique</span></span> (<span>condition précancéreuse</span>) ; un <span>cancer débutant</span> peut mimer un UG bénin</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Conséquence pratique — </strong>la découverte d'un <span><span class=\"nc-red nc-bold\">ulcère gastrique</span></span> impose des <span>biopsies des berges</span> (6 à 12) en plus des biopsies de l'<span class=\"nc-red nc-bold\">antre</span> et du fundus, à la recherche d'un <span class=\"nc-red nc-bold\">cancer</span> et de <span>lésions précancéreuses</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","contenu":"<div class=\"notion-course\"><ul><li>Si la sensibilité à la <span class=\"nc-pink_bg\">clarithromycine</span> est démontrée : dix jours d’<span class=\"nc-green_bg\">IPP</span> à dose standard deux fois/jour, <span class=\"nc-pink_bg\">amoxicilline</span> 50 mg/kg/j en trois ou quatre prises et <span class=\"nc-pink_bg\">clarithromycine</span> 500 mg deux fois/jour, selon HAS et contre-indications.</li><li>Si résistance à la <span class=\"nc-pink_bg\">clarithromycine</span> mais sensibilité à la <span class=\"nc-pink_bg\">lévofloxacine</span> : dix jours d’<span class=\"nc-green_bg\">IPP</span>, <span class=\"nc-pink_bg\">amoxicilline</span> et <span class=\"nc-pink_bg\">lévofloxacine</span> 500 mg/j selon HAS. Évaluer les risques spécifiques des fluoroquinolones.</li><li>Si résistance aux deux : quadrithérapie bismuthée dix jours, <span class=\"nc-green_bg\">oméprazole</span> 20 mg deux fois/jour et association bismuth–métronidazole–<span class=\"nc-pink_bg\">tétracycline</span> selon RCP. En l’absence de sensibilité documentée, suivre le schéma probabiliste recommandé, sans improviser une trithérapie.</li><li>Vérifier <span class=\"nc-green nc-bold\">l’éradication</span> par test respiratoire au moins quatre <span class=\"nc-pink nc-bold\">semaines</span> après les antibiotiques et après au moins deux <span class=\"nc-pink nc-bold\">semaines</span> sans <span class=\"nc-pink nc-bold\">IPP</span>. Adapter la poursuite des <span class=\"nc-pink nc-bold\">IPP</span> à <span class=\"nc-pink nc-bold\">l’ulcère</span>, sa complication et sa <span class=\"nc-green_bg nc-bold\">cicatrisation</span> ; contrôle <span class=\"nc-blue nc-bold\">endoscopique</span> d’un ulcère gastrique.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":5},{"id":"272-16","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une gastrite","contenu":"<div class=\"notion-course\"><p><strong><span><span class=\"nc-yellow_bg\">Gastrite</span></span></strong> — <span>lésions inflammatoires aiguës ou chroniques de la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique</span>. C'est un diagnostic <strong>histologique</strong> : <span>5 <span class=\"nc-red nc-bold\">biopsies</span></span> sont recommandées pour le diagnostic (<span><span class=\"nc-blue nc-bold\">2 fundus</span>, <span class=\"nc-blue nc-bold\">2 antre</span>, <span class=\"nc-blue nc-bold\">1 angle de la petite courbure</span></span>).</p>\n      <p><strong><span class=\"nc-yellow_bg\">Gastropathie</span></strong> — <span>affection diffuse de la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique <span class=\"nc-pink nc-bold\">sans infiltrat inflammatoire</span></span> ; à distinguer de la <span><span class=\"nc-yellow_bg\">gastrite</span></span>.</p>\n      <div class=\"callout callout-warn\"><strong>❌ Pas de corrélation — </strong>aucune corrélation entre l'<span>histologie et la <span class=\"nc-red nc-bold\">symptomatologie</span></span>, ni entre l'<span>histologie et l'aspect <span class=\"nc-blue_bg\">endoscopique</span></span>. « <span><span class=\"nc-yellow_bg\">Gastrite</span></span> » est un <span>diagnostic histologique</span> : on n'en parle ni pour décrire des symptômes, ni pour décrire des <span><span class=\"nc-blue_bg\">lésions endoscopiques</span></span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":0},{"id":"272-17","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types de gastrite","contenu":"<div class=\"notion-course\"><p>La <strong><span>classification</span> de Sydney</strong> repose sur trois caractéristiques principales :</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Étiologie</td><td>La cause de la <span>gastrite</span></td></tr>\n          <tr><td>Topographie</td><td><span>Gastrite</span> <span><span class=\"nc-blue nc-bold\">fundique</span></span> (maladie de Biermer) ou <span><span class=\"nc-blue nc-bold\">antrale</span></span> (<span>H. pylori</span>)</td></tr>\n          <tr><td>Morphologie</td><td>Siège et densité de l'infiltrat <span>inflammatoire</span>, caractère <span>actif</span> (PNN présents) ou inactif, degré d'<span class=\"nc-red\">atrophie</span> muqueuse et de <span class=\"nc-red nc-bold\">métaplasie intestinale</span>, <span class=\"nc-purple_bg\">présence</span> <span class=\"nc-red nc-bold\">d'agents pathogènes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principaux types de <span>gastrite</span> :</strong></p>\n      <table>\n        <thead><tr><th>Type</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>À <span>H. pylori</span></td><td>De loin la <strong>plus fréquente</strong> ; topographie <span>antrale</span></td></tr>\n          <tr><td><span>Auto-immune</span> (Biermer)</td><td>Topographie <span><span class=\"nc-blue nc-bold\">fundique</span></span> ; <span class=\"nc-red_bg\">atrophie progressive des glandes du fundus</span></td></tr>\n          <tr><td>Lymphocytaire</td><td>Association possible à une <span>maladie cœliaque</span>, une <span>colite lymphocytaire</span> ou une <span><span class=\"nc-purple nc-bold\">infection</span> à H. pylori</span></td></tr>\n          <tr><td>À <span class=\"nc-blue_bg nc-bold\">collagène</span></td><td><span>Bande de <span class=\"nc-blue_bg nc-bold\">collagène</span> sous-épithéliale</span> ; rare ; association possible à une <span>colite <span class=\"nc-blue_bg nc-bold\">collagène</span></span> ou une <span>maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span><span class=\"nc-purple nc-bold\">Crohn</span>, <span class=\"nc-purple nc-bold\">sarcoïdose</span>, <span class=\"nc-purple nc-bold\">tuberculose</span>, <span class=\"nc-purple nc-bold\">syphilis</span></span>, parasites</td></tr>\n          <tr><td>À <span>éosinophiles</span></td><td><span><span class=\"nc-red nc-bold\">Allergie alimentaire</span>, <span class=\"nc-red nc-bold\">parasitose</span></span> (anisakiase)</td></tr>\n          <tr><td><span>Virale</span></td><td><span>CMV, HSV</span> ; surtout l'immunodéprimé</td></tr>\n          <tr><td>Phlegmoneuse</td><td><span><span class=\"nc-purple nc-bold\">Infection</span> <span class=\"nc-purple nc-bold\">bactérienne</span></span> sévère de la paroi gastrique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gastropathies</strong> (≠ <span>gastrite</span>, <span class=\"nc-pink nc-bold\">sans infiltrat </span><span><span class=\"nc-pink nc-bold\">inflammatoire</span></span>) : induite par <span>les</span> <span>AINS</span> ; chimique (<span>alcool</span>, <span class=\"nc-brown_bg\">reflux</span> biliaire post-gastrectomie) ; congestive (<span>HTP</span>, ectasies vasculaires antrales) ; hypertrophique (<span class=\"nc-orange_bg\">maladie de Ménétrier</span>) ; radique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":1},{"id":"272-18","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les causes de la gastrite","contenu":"<div class=\"notion-course\"><p><strong>Rappel anatomo-fonctionnel</strong> — <span>les</span> glandes gastriques diffèrent selon le type de muqueuse :</p>\n      <table>\n        <thead><tr><th>Glandes</th><th>Cellules &amp; sécrétions</th></tr></thead>\n        <tbody>\n          <tr><td>Fundiques</td><td><span><span class=\"nc-blue_bg\">Cellules pariétales</span></span> (<span class=\"nc-pink nc-bold\">HCl</span> + <span class=\"nc-pink nc-bold\">facteur intrinsèque</span>) ; <span><span class=\"nc-blue_bg\">cellules principales</span></span> (<span class=\"nc-pink nc-bold\">pepsinogène</span>) ; <span><span class=\"nc-blue_bg\">cellules ECL</span></span> (<span class=\"nc-pink nc-bold\">histamine</span>)</td></tr>\n          <tr><td>Antrales</td><td><span class=\"nc-yellow_bg\">Cellules </span><span><span class=\"nc-yellow_bg\">mucosécrétantes</span></span> ; <span class=\"nc-yellow_bg\">cellules endocrines </span><span><span class=\"nc-yellow_bg\">à gastrine</span></span> (stimule l'HCl fundique et <span>les</span> cellules ECL)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes de <span>gastrite</span> :</strong></p>\n      <table>\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span>H. pylori</span></td><td>La <strong>1re cause</strong> ; <span>gastrite</span> <span class=\"nc-blue nc-bold\">antrale</span></td></tr>\n          <tr><td><span>Auto-immune</span> (Biermer)</td><td><span>Gastrite</span> <span><span class=\"nc-blue nc-bold\">fundique</span></span> ; sujet <span>&gt; 50 ans</span>, prédominance <span class=\"nc-brown_bg\">féminine</span> ; l'<span class=\"nc-red\">atrophie</span> <span class=\"nc-blue nc-bold\">fundique</span> entraîne une <span><span class=\"nc-orange_bg\">carence en B12</span></span>, une <span><span class=\"nc-orange_bg\">carence martiale</span></span> et une <span><span class=\"nc-blue nc-bold\">hypergastrinémie réactionnelle</span></span> (risque de TNE à cellules ECL) ; séquence <span class=\"nc-red\">atrophie</span> → <span class=\"nc-red\">métaplasie</span> → <span class=\"nc-red\">dysplasie</span> → <span><span class=\"nc-red nc-bold\">adénocarcinome</span></span></td></tr>\n          <tr><td>Lymphocytaire</td><td>Association à une <span>maladie cœliaque</span></td></tr>\n          <tr><td>À <span class=\"nc-blue_bg nc-bold\">collagène</span></td><td>Rare ; <span>dépôt de <span class=\"nc-blue_bg nc-bold\">collagène</span> sous-épithélial</span> ; à rapprocher de la colite <span class=\"nc-blue_bg nc-bold\">collagène</span> et de la <span>maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span><span class=\"nc-purple nc-bold\">Crohn</span>, <span class=\"nc-purple nc-bold\">sarcoïdose</span>, <span class=\"nc-purple nc-bold\">tuberculose</span>, <span class=\"nc-purple nc-bold\">syphilis</span></span>, parasites, mycoses</td></tr>\n          <tr><td>À <span>éosinophiles</span></td><td><span><span class=\"nc-red nc-bold\">Allergie alimentaire</span>, anisakiase</span></td></tr>\n          <tr><td>Associée à Crohn</td><td>Atteinte gastrique chez ≈ <span>30 %</span> des patients atteints de Crohn</td></tr>\n          <tr><td>Infectieuse</td><td><span>Virale</span> (<span><span class=\"nc-purple nc-bold\">CMV</span>, <span class=\"nc-purple nc-bold\">HSV</span></span>), phlegmoneuse (<span><span class=\"nc-purple nc-bold\">bactérienne</span></span>) — surtout l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":2},{"id":"272-19","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et la place des biopsies pour le diagnostic, le traitement et le suivi","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">gastrite</span></span> est un diagnostic <strong>histologique</strong> : <span>5 biopsies</span> (<span class=\"nc-blue nc-bold\">2 fundus</span>, <span <span=\"\">&gt;<span class=\"nc-blue nc-bold\">2</span></span><span class=\"nc-blue nc-bold\"> antre</span>, <span class=\"nc-blue nc-bold\">1 angle de la petite courbure</span>). Il n'existe pas de corrélation entre l'aspect <span class=\"nc-blue_bg\">endoscopique</span>, l'<span>histologie</span> et <span>les</span> symptômes.</p>\n      <p><strong>Indications des biopsies</strong> selon l'aspect <span class=\"nc-blue_bg\">endoscopique</span> de la muqueuse :</p>\n      <table>\n        <thead><tr><th>Situation</th><th>Objectif des biopsies</th></tr></thead>\n        <tbody>\n          <tr><td>Présence d'une <span>lésion</span> endoscopique</td><td>Confirmer le diagnostic de <span><span class=\"nc-yellow_bg\">gastrite</span></span> et en déterminer la cause</td></tr>\n          <tr><td>Absence de <span>lésion</span> <span class=\"nc-blue_bg\">endoscopique</span></td><td>Rechercher une pathologie spécifique : <span><span class=\"nc-orange_bg\">carence en B12</span> avec anémie macrocytaire</span> (recherche d'<span class=\"nc-red\">atrophie</span>), ATCD familial de <span class=\"nc-red nc-bold\">cancer gastrique</span>, <span class=\"nc-orange_bg nc-bold\">douleurs</span> abdominales chroniques (recherche d'<span><span class=\"nc-pink_bg\">H. pylori</span></span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"nc-yellow_bg\">Traitement</span></strong> — une fois le diagnostic posé, il est <span>ciblé sur la cause</span> identifiée : éradication d'HP, arrêt de l'<span>alcool</span>, <span class=\"nc-yellow_bg\">traitement</span> de l'<span>hypertension</span> portale…</p>\n      <div class=\"callout callout-danger\"><strong><span>Suivi</span> — </strong>une <span><span class=\"nc-blue nc-bold\">surveillance endoscopique</span> à vie</span> avec <span class=\"nc-red nc-bold\">biopsies</span> est nécessaire pour : la <span><span class=\"nc-yellow_bg\">gastrite</span> auto-immune de Biermer</span> (risque d'<span class=\"nc-red nc-bold\">adénocarcinome</span> et de tumeur neuro-endocrine) ; la <span><span class=\"nc-yellow_bg\">gastrite</span> à risque de dégénérescence</span> séquellaire d'une <span class=\"nc-purple nc-bold\">infection</span> à HP (<span class=\"nc-red\">atrophie</span>, <span class=\"nc-red\">métaplasie</span>, <span class=\"nc-red\">dysplasie</span> = <span>lésions précancéreuses</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac · 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La surveillance d’une <span class=\"nc-red\">atrophie</span> ou <span class=\"nc-red\">métaplasie</span> gastrique dépend de l’étendue, de l’histologie, des facteurs de risque et de l’âge ; elle n’est pas systématiquement annuelle ou à vie pour toute <span class=\"nc-yellow_bg\">gastrite</span>.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":3},{"id":"272-20","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la gastrite","contenu":"<div class=\"notion-course\"><p>Le traitement d'une <span>gastrite</span> consiste à <strong>traiter la cause</strong> identifiée :</p>\n      <table>\n        <thead><tr><th>Cause</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span>Gastrite</span> à H. pylori</td><td><span>Éradication d'H. pylori</span></td></tr>\n          <tr><td>Biermer (<span>auto-immune</span>)</td><td>Biermer : supplémentation durable en vitamine B12, classiquement parentérale ; voie orale à forte dose envisageable dans des situations sélectionnées avec suivi adapté. Corriger une <span class=\"nc-orange_bg\">carence martiale</span> associée. <span class=\"nc-blue nc-bold\">Surveillance endoscopique</span> selon <span class=\"nc-yellow_bg\">gastrite</span> atrophique, lésions et terrain ; le seuil de soixante-dix ans n’est pas une règle universelle d’arrêt.</td></tr>\n          <tr><td>Gastropathie chimique</td><td><span>Arrêt de l'alcool</span> ou de la cause</td></tr>\n          <tr><td>Gastropathie d'<span>HTP</span></td><td>Traitement de l'<span>hypertension portale</span></td></tr>\n          <tr><td>Causes spécifiques</td><td>Traitement étiologique (<span><span class=\"nc-purple_bg nc-bold\">CMV</span></span>, <span>Crohn</span>…)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-orange nc-bold\">Carence</span> en vitamine B12 : correction indispensable, voie parentérale ou orale à forte dose selon gravité, cause et suivi. Une atteinte neurologique ou une situation sévère impose une prise en charge rapide adaptée.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3282789/fr/choix-et-duree-de-l-antibiotherapie-traitement-guide-de-l-infection-par-helicobacter-pylori-chez-l-adulte\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · traitement guidé de Helicobacter pylori</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3372966/fr/fiche-bum-bon-usage-des-inhibiteurs-de-la-pompe-a-protons-ipp\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · bon usage des IPP</a></li><li><a href=\"https://www.esge.com/assets/downloads/pdfs/guidelines/2026_a-2863-8314.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ESGE · ulcère hémorragique, recommandations 2026</a></li></ul></details>","frequence":0}],"astuces":[{"type":"tip","titre":"Mnémonique du syndrome ulcéreux","contenu":"Ulcère gastrique = douleur <strong>après</strong> le repas (post-prandial) comme si l'estomac se faisait gronder. Ulcère duodénal = douleur <strong>à jeun / nocturne</strong>, calmée par l'alimentation. Mnémotechnique : <em>« Gastro = Grincheux après manger ; Duodéno = Dormeur réveillé la nuit »</em>."},{"type":"danger","titre":"Toujours biopsier un ulcère gastrique","contenu":"Contrairement à l'ulcère duodénal (bénin), l'ulcère gastrique porte un risque de malignité. <strong>4 à 6 biopsies sur les bords + fond</strong> sont obligatoires. Un contrôle endoscopique à 6-8 sem est indispensable pour confirmer la cicatrisation et exclure un cancer masqué."},{"type":"warn","titre":"Test de guérison HP : les pièges de timing","contenu":"L'UBT (test respiratoire) et l'antigène fécal sont falsifiés par les IPP et les antibiotiques. Il faut impérativement attendre <strong>≥ 4 sem après la fin des antibiotiques</strong> et <strong>≥ 2 sem après l'arrêt de l'IPP</strong> pour un résultat fiable. Sinon : faux négatifs fréquents et échec thérapeutique méconnu."},{"type":"info","titre":"Classification de Forrest et conduite endoscopique","contenu":"Forrest Ia (saignement actif artériel) et Ib (veineux) = hémostase endoscopique <strong>impérative</strong>. Forrest IIa (vessel visible non saignant) et IIb (coagulum) = hémostase préventive recommandée. Forrest IIc (tache hematique) et III (fond propre) = pas d'hemostase endoscopique, IPP per os suffisant."},{"type":"tip","titre":"Gastrite autoimmune : ne pas oublier la B12","contenu":"La gastrite autoimmune détruit les cellules pariétales → absence de facteur intrinsèque et d'acide chlorhydrique. Résultat inévitable : <strong>anémie de Biermer</strong> (carence en B12) avec macrocytose et éventuellement neurologie (funis). Traitement : vitamine B12 per os à vie (1 mg/j) car dose massive permet absorption passive."}],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">UGD</span> non compliqué</strong></p><p>diagnostic et traitement en ambulatoire</p><ul><li>pas d'<span class=\"kw-alerte\">urgence</span></li></ul><p><strong><span class=\"kw-clinique\">Hémorragie digestive haute</span></strong></p><p><span class=\"kw-ttt\">IPP IV</span> en continu sans retarder l'<span class=\"kw-imagerie\">EOGD</span> ; <span class=\"kw-imagerie\">endoscopie</span> diagnostique et thérapeutique dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span></p><ul><li><span class=\"kw-alerte\">urgence vitale</span> (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">≈ 10 %</span>)</li></ul><p><strong>Perforation peritonisée</strong></p><p><span class=\"kw-imagerie\">TDM AP injectée</span> en 1ʳᵉ intention, <span class=\"kw-ci\">EOGD formellement contre-indiquée</span></p><ul><li><span class=\"kw-alerte\">urgence chirurgicale</span> après <strong>courte <span class=\"kw-alerte\">réanimation</span></strong></li></ul><p><strong>Contracture abdominale</strong></p><p>1er geste = <span class=\"kw-imagerie\">TDM AP injectée</span> (pneumopéritoine + réaction <span class=\"kw-etio\">inflammatoire</span> antro-pyloro-bulbaire)</p><p><strong>Sténose ulcéreuse</strong></p><ul><li>non urgent mais bilan <span class=\"kw-alerte\">hospitalisation</span> (alcalose métabolique, dénutrition) avant <span class=\"kw-ttt\">chirurgie</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">UGD</span> non compliqué (diagnostic à l'<span class=\"kw-imagerie\">EOGD</span>, traitement <span class=\"kw-ttt\">IPP</span> ± éradication HP, <span class=\"kw-def\">suivi</span> clinique).</p><p><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle :</strong> hémorragie digestive stabilisée (<span class=\"kw-def\">Forrest IIc-III</span>), sténose à bilanter, perforation-bouchée stable.</p><p><strong><span class=\"kw-alerte\">USI</span> / Réanimation :</strong> <span class=\"kw-alerte\">choc hémorragique</span>, instabilité hémodynamique persistante, transfusion massive, <span class=\"kw-clinique\">troubles de conscience</span>, saignement actif au scope.</p><p><strong><span class=\"kw-ttt\">Chirurgie</span> d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-clinique\">péritonite</span> par perforation ; hémorragie <span class=\"kw-alerte\">réfractaire</span> à l'<span class=\"kw-ttt\">hémostase endoscopique</span> + <span class=\"kw-ttt\">embolisation artérielle</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Contracture abdominale</span> / <span class=\"kw-clinique\">défense</span>, douleur au TR (Douglas douloureux) — <span class=\"kw-clinique\">péritonite</span> par perforation</li><li><span class=\"kw-alerte\">Tympanisme + disparition de la matité préhépatique</span> — pneumopéritoine clinique (signe quasi-pathognomonique)</li><li><span class=\"kw-alerte\">Hématémèse</span>, <span class=\"kw-alerte\">méléna</span>, sang rouge au toucher rectal — hémorragie digestive extériorisée</li><li><span class=\"kw-clinique\">Tachycardie</span> <span class=\"kw-chiffre\">&gt; 100 bpm</span> (meilleur signe précoce de <span class=\"kw-alerte\">défaillance</span> HD) ; <span class=\"kw-alerte\">bradycardie</span> = gravité extrême ; <span class=\"kw-clinique\">hypotension</span> artérielle</li><li>Hypoperfusion : <span class=\"kw-clinique\">marbrures</span>, allongement du TRC, oligurie <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span>, <span class=\"kw-clinique\">troubles de la vigilance</span></li><li><span class=\"kw-clinique\">Vomissements post-prandiaux tardifs</span> + <span class=\"kw-bio\">alcalose métabolique hypochlorémique hypokaliémique</span> — sténose ulcéreuse</li><li><span class=\"kw-alerte\">Amaigrissement</span>, <span class=\"kw-clinique\">ganglion de Troisier</span> (<span class=\"kw-clinique\">adénopathie</span> sus-claviculaire G) — cancer associé sur ulcère gastrique</li><li><span class=\"kw-clinique\">Ulcère duodénal post-bulbaire</span> (très rare) — évoquer <span class=\"kw-etio\">Zollinger-Ellison</span> ou <span class=\"kw-etio\">MICI</span> (Crohn, <span class=\"kw-clinique\">vascularite</span>)</li><li><span class=\"kw-def\">Terrain</span> à risque de forme compliquée : <span class=\"kw-chiffre\">âge &gt; 65 ans</span>, ATCD d'<span class=\"kw-clinique\">UGD</span> compliqué, <span class=\"kw-ttt\">AINS</span> + <span class=\"kw-etio\">H. pylori</span>, <span class=\"kw-ttt\">anticoagulants</span></li></ul>","principes":"<p>Couvrir l'<span class=\"kw-clinique\">UGD</span> par <span class=\"kw-ttt\">IPP</span> (cicatrisation requiert <span class=\"kw-chiffre\">pH &gt; 3</span>), <span class=\"kw-ttt\">éradiquer H. pylori</span> (prévention de la récidive ≈ constante si non éradiqué), traiter le facteur favorisant (arrêt <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span> si possible), contrôler la <strong>cicatrisation</strong> (<span class=\"kw-imagerie\">EOGD</span> systématique pour l'UG, biopsies des berges).</p><p><strong>Ulcère duodénal non compliqué</strong></p><ul><li><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span></li><li>pas de contrôle endoscopique si patient asymptomatique</li></ul><p><strong>Ulcère gastrique non compliqué</strong></p><ul><li><span class=\"kw-ttt\">IPP simple dose</span> pendant <span class=\"kw-chiffre\">4 à 8 semaines</span> + <span class=\"kw-imagerie\">contrôle endoscopique systématique</span> de la cicatrisation avec biopsies (zone cicatricielle + recherche HP)</li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— quadrithérapie bismuthée</span></strong></p><ul><li><span class=\"kw-ttt\">métronidazole + tétracycline + oméprazole double dose + sous-citrate de bismuth</span> sur <span class=\"kw-chiffre\">10 jours</span> — si <span class=\"kw-ci\">allergie aux β-lactamines</span>, sensibilités non connues, résistance à <span class=\"kw-ttt\">clarithromycine</span>/<span class=\"kw-ttt\">lévofloxacine</span></li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— quadrithérapie concomitante</span></strong></p><ul><li><span class=\"kw-ttt\">métronidazole + amoxicilline + clarithromycine + IPP double dose</span> sur <span class=\"kw-chiffre\">14 jours</span> — sensibilités non connues sans <span class=\"kw-ci\">allergie</span></li></ul><p><strong>Éradication <span class=\"kw-clinique\">H. pylori</span> <span class=\"q\">— <span class=\"kw-ttt\">trithérapie</span> ciblée</span></strong></p><ul><li><span class=\"kw-ttt\">amoxicilline + IPP double dose + clarithromycine</span> (ou <span class=\"kw-ttt\">lévofloxacine</span> si résistance) sur <span class=\"kw-chiffre\">10 jours</span> — sensibilité connue, pas d'<span class=\"kw-ci\">allergie</span></li></ul><p><strong><span class=\"kw-clinique\">UGD</span> induit <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span></strong></p><ul><li>traitement standard + <span class=\"kw-ttt\">IPP de maintien</span> si <span class=\"kw-ttt\">AINS</span> indispensable</li><li><span class=\"kw-ttt\">IPP préventif</span> si <span class=\"kw-chiffre\">âge &gt; 65 ans</span>, ATCD <span class=\"kw-clinique\">UGD</span>, <span class=\"kw-ttt\">anti-thrombotique</span> ou <span class=\"kw-ttt\">corticoïdes</span> associés</li></ul><p><strong>Hémorragie ulcéreuse <span class=\"q\">— <span class=\"kw-alerte\">réanimation</span></span></strong></p><ul><li>2 VVP, oxygénation, scope, bilan (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">2 groupages + RAI</span>, <span class=\"kw-bio\">créatinine</span>), antagonisation des <span class=\"kw-ttt\">anticoagulants</span>, <span class=\"kw-ttt\">IPP IV en continu</span> sans retarder l'<span class=\"kw-imagerie\">EOGD</span></li></ul><p><strong>Hémorragie Forrest Ia-IIb <span class=\"q\">(signes endoscopiques de gravité)</span></strong></p><ul><li><span class=\"kw-ttt\">hémostase endoscopique</span> (thermocoagulation + clips ± sérum adrénaliné) + <span class=\"kw-ttt\">IPP fortes doses en IV continu pendant 48-72 h</span>, puis relais per os à pleine dose</li></ul><p><strong>Hémorragie Forrest IIc-III</strong></p><ul><li><span class=\"kw-ttt\">IPP pleine dose per os</span> d'emblée + <span class=\"kw-def\">surveillance</span></li><li>pas d'hémostase endoscopique nécessaire</li></ul><p><strong>Hémorragie réfractaire</strong></p><ul><li><span class=\"kw-ttt\">embolisation artérielle</span> (artère gastro-duodénale ou gastrique gauche selon localisation), puis <span class=\"kw-ttt\">chirurgie</span> d'hémostase si échec</li></ul><p><strong>Perforation peritonisée</strong></p><ul><li><span class=\"kw-ttt\">chirurgie</span> d'<span class=\"kw-alerte\">urgence</span> (suture-épiploplastie ou résection) + <span class=\"kw-ttt\">antibiothérapie probabiliste IV</span> couvrant flore digestive</li><li><span class=\"kw-ci\">EOGD contre-indiquée</span></li></ul><p><strong>Perforation-bouchée stable <span class=\"q\">(méthode de Taylor)</span></strong></p><ul><li>SNG en aspiration + <span class=\"kw-ttt\">IPP IV</span> + <span class=\"kw-ttt\">antibiotiques IV</span> + jeûne strict, sous <span class=\"kw-def\">surveillance</span> clinique rapprochée — uniquement en l'absence de <span class=\"kw-alerte\">signe de gravité</span></li></ul><p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— objectifs</span></strong></p><ul><li>remplissage par cristalloïdes ± <span class=\"kw-ttt\">noradrénaline</span> si PAS &lt;<span class=\"kw-chiffre\"> 80 mmHg</span> malgré<span class=\"kw-chiffre\"> 1-1,5 L</span> ± transfusion</li><li>cibles <span class=\"kw-chiffre\">FC &lt; 100 bpm</span>, <span class=\"kw-chiffre\">PAS &gt; 100 mmHg</span> (ou PAM <span class=\"kw-chiffre\">≥ 65</span>), diurèse &gt;<span class=\"kw-chiffre\"> 0,5 mL</span>/kg/h, <span class=\"kw-chiffre\">Hb 7-9 g/dL</span> (7-8 si varices, &gt; 9 si <span class=\"kw-def\">comorbidités</span> cardiovasculaires)</li></ul><p><strong><span class=\"kw-clinique\">Gastrite</span> <span class=\"q\">— principe</span></strong></p><ul><li>traitement <span class=\"kw-ttt\">étiologique ciblé</span> (éradication HP, arrêt <span class=\"kw-etio\">alcool</span>, supplémentation <span class=\"kw-ttt\">B12 parentérale</span> si Biermer, traitement de l'<span class=\"kw-clinique\">HTP</span> pour gastropathie congestive)</li></ul>","suivi":"<p><strong>Contrôle d'éradication <span class=\"kw-clinique\">H. pylori</span> — systématique</strong> (≈ <span class=\"kw-chiffre\">10 %</span> d'échec en 1ʳᵉ ligne) : <span class=\"kw-chiffre\">4 semaines après la fin des antibiotiques</span> et <span class=\"kw-chiffre\">2 semaines après l'arrêt des IPP</span>.</p><p><strong>UD ou <span class=\"kw-def\">dépistage</span> :</strong> <span class=\"kw-bio\">test respiratoire à l'urée marquée C13</span> (seul test remboursé pour le contrôle).</p><p><strong>UG :</strong> <span class=\"kw-imagerie\">contrôle endoscopique impératif</span> avec biopsies de la zone cicatricielle (recherche d'<span class=\"kw-etio\">adénocarcinome</span> + contrôle HP).</p><p><strong>Échec d'éradication :</strong> switch de schéma sans <span class=\"kw-imagerie\">EOGD</span> puis nouveau contrôle ; en cas de nouvel échec, <span class=\"kw-imagerie\">EOGD + biopsies avec étude de la sensibilité aux antibiotiques</span>.</p><p><strong><span class=\"kw-def\">Surveillance</span> endoscopique à vie :</strong> <span class=\"kw-etio\">gastrite auto-immune de Biermer</span> (risque d'adénocarcinome et de TNE à cellules ECL) ; <span class=\"kw-alerte\">lésions précancéreuses séquellaires d'HP</span> (atrophie sévère, métaplasie intestinale, dysplasie).</p><p><strong>Pas d'<span class=\"kw-ttt\">IPP</span> au long cours</strong> après éradication HP si UD non compliqué ; <span class=\"kw-ttt\">IPP curatif 6 semaines</span> si UG ou UD compliqué, ou douleurs persistantes, ou poursuite d'<span class=\"kw-ttt\">AINS</span> / antithrombotiques.</p>"},"liensGlobaux":[{"href":"https://facmed-univ-oran.dz/ressources/fichiers_produits/fichier_produit_2037.pdf","label":"Fichier produit 2037"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur épigastrique évocatrice d'UGD — Premier tri clinique","detail":"<h4>CAT — suspicion d'<span class=\"kw-clinique\">UGD</span> — Orientation initiale : perforation / hémorragie / forme non compliquée</h4>","branches":[{"to":"q-tdm-pneumo","label":"Contracture / défense abdominale","color":"red"},{"to":"q-forrest","label":"Hématémèse / méléna / instabilité HD","color":"red"},{"to":"q-eogd","label":"Ni contracture ni saignement","color":"green"}]},{"id":"q-tdm-pneumo","kind":"decision","label":"TDM abdomino-pelvienne injectée — pneumopéritoine ? — Examen de 1ʳᵉ intention · EOGD contre-indiquée","branches":[{"to":"q-stabilite-perfo","label":"Oui — péritonite confirmée","color":"red"},{"to":"t-reeval","label":"Non — pas de pneumopéritoine","color":"blue"}]},{"id":"q-stabilite-perfo","kind":"decision","label":"Stabilité hémodynamique + absence de sepsis ? — Recherche d'une perforation-bouchée stable","branches":[{"to":"t-chirurgie","label":"Non — instable / sepsis","color":"red"},{"to":"t-taylor","label":"Oui — perforation-bouchée stable","color":"amber"}]},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie en urgence","color":"red","detail":"<h4>Délai</h4><ul><li>Intervention chirurgicale en <span class=\"kw-alerte\">urgence</span>, précédée d'une courte <span class=\"kw-alerte\">réanimation</span>.</li></ul><h4>Conduite</h4><ul><li>Suture-épiploplastie (ulcère simple) ou résection (ulcère gastrique suspect de néoplasie)</li><li><span class=\"kw-ttt\">Antibiothérapie probabiliste IV</span> couvrant la flore digestive (entérobactéries, <span class=\"kw-etio\">anaérobies</span>, entérocoques)</li><li>Toilette péritonéale per-opératoire</li><li><span class=\"kw-ttt\">IPP IV</span> en post-op</li></ul><h4>Piège</h4><ul><li><span class=\"kw-ci\">EOGD formellement contre-indiquée</span> en cas de perforation (risque d'aggravation par insufflation).</li></ul>"},{"id":"t-taylor","kind":"terminal","label":"Méthode de Taylor (traitement médical)","color":"amber","detail":"<h4>Indication</h4><ul><li>Perforation au <span class=\"kw-def\">contact</span> du pancréas (perforation-bouchée), régression de la douleur initiale, <span class=\"kw-alerte\">pas de pneumopéritoine</span> (possible rétro-pneumopéritoine), en l'absence de <span class=\"kw-alerte\">signe de gravité</span>.</li></ul><h4>Conduite</h4><ul><li>SNG en aspiration continue</li><li><span class=\"kw-ttt\">IPP IV</span></li><li><span class=\"kw-ttt\">Antibiotiques IV</span></li><li>Jeûne strict, repos digestif</li><li><span class=\"kw-def\">Surveillance</span> clinique rapprochée (douleur, <span class=\"kw-clinique\">fièvre</span>, hémodynamique)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> de sauvetage si apparition de signes péritonéaux, <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc</span>.</li></ul>"},{"id":"t-reeval","kind":"terminal","label":"Réévaluation diagnostique","color":"blue","detail":"<h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-clinique\">Pancréatite aiguë</span> (lipasémie, <span class=\"kw-imagerie\">scanner</span> pancréatique)</li><li>Ischémie mésentérique (<span class=\"kw-imagerie\">scanner</span> injecté, <span class=\"kw-bio\">lactates</span>)</li><li><span class=\"kw-clinique\">Cholécystite</span>, angiocholite</li><li><span class=\"kw-clinique\">Infarctus</span> du myocarde inférieur (<span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-bio\">troponine</span>)</li><li>Colique néphrétique compliquée</li></ul><h4>Conduite</h4><ul><li>Compléter le bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">lipase</span>, <span class=\"kw-bio\">troponine</span>, <span class=\"kw-bio\">lactates</span>, BHC) et imageries ciblées. Pas d'<span class=\"kw-imagerie\">EOGD</span> tant que la perforation n'est pas formellement éliminée.</li></ul>"},{"id":"q-forrest","kind":"decision","label":"EOGD en urgence — classification de Forrest ? — Après réanimation hémodynamique + IPP IV continu, sans retarder l'endoscopie","branches":[{"to":"t-hemostase","label":"Ia–IIb · signes endoscopiques de gravité","color":"red"},{"to":"t-ipp-po","label":"IIc–III · pas de signes de gravité","color":"amber"}]},{"id":"t-hemostase","kind":"terminal","label":"Hémostase endoscopique + IPP IV continu 48-72 h","color":"red","detail":"<h4>Stades concernés</h4><ul><li>Ia : hémorragie en jet (artérielle active)</li><li>Ib : suintement diffus</li><li>IIa : vaisseau visible non <span class=\"kw-etio\">hémorragique</span></li><li>IIb : caillot adhérent</li></ul><h4>Traitement endoscopique</h4><ul><li>Thermocoagulation + clips ± injection de sérum adrénaliné (double méthode recommandée)</li><li><span class=\"kw-ttt\">IPP fortes doses en IV continu pendant 48-72 h</span></li><li>Puis relais per os à pleine dose</li></ul><h4>Échec endoscopique</h4><ul><li><span class=\"kw-ttt\">Embolisation artérielle</span> en 2ᵉ intention (artère gastro-duodénale si UD postérieur, artère gastrique gauche si UG petite courbure), puis <span class=\"kw-ttt\">chirurgie</span> d'hémostase en 3ᵉ intention.</li></ul><h4>Recherche HP</h4><ul><li>En contexte <span class=\"kw-etio\">hémorragique</span>, biopsies non réalisables → <span class=\"kw-bio\">sérologie HP</span> (annale EDN).</li></ul>"},{"id":"t-ipp-po","kind":"terminal","label":"IPP pleine dose per os + surveillance","color":"amber","detail":"<h4>Stades concernés</h4><ul><li>IIc : taches p<span class=\"kw-chiffre\">igm</span>entées (hématine)</li><li>III : cratère à fond propre</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP pleine dose per os</span> d'emblée, pas d'IV continu nécessaire</li><li>Pas d'hémostase endoscopique (risque <span class=\"kw-etio\">hémorragique</span> faible)</li><li><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle, scope, <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-ttt\">biologique</span></li></ul><h4>À distance</h4><ul><li>Recherche d'<span class=\"kw-etio\">H. pylori</span> dès que possible (biopsies), <span class=\"kw-ttt\">éradication</span> si positive ; arrêt des <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">aspirine</span> si non indispensables.</li></ul>"},{"id":"q-eogd","kind":"decision","label":"Indications d'EOGD ? — Âge > 50 ans · signes d'alarme (dysphagie, amaigrissement, hémorragie, anémie) · échec du traitement symptomatique","branches":[{"to":"t-eogd-diag","label":"Oui — au moins 1 critère","color":"blue"},{"to":"t-ipp-test","label":"Non — patient jeune sans red flag","color":"green"}]},{"id":"t-eogd-diag","kind":"terminal","label":"EOGD diagnostique avec biopsies HP","color":"blue","detail":"<h4>Modalités</h4><ul><li>Anesthésie locale pharyngée (AG non nécessaire)</li><li>Description de l'ulcère : perte de substance creusante, fond pseudo-membraneux blanchâtre, bords réguliers</li></ul><h4>Biopsies</h4><ul><li><span class=\"kw-alerte\">Recherche HP systématique</span> : biopsies gastriques antrales ET fundiques (<span class=\"kw-alerte\">jamais duodénales</span>)</li><li>Si UG : <span class=\"kw-chiffre\">6 à 12 biopsies des berges</span> en plus, à la recherche d'<span class=\"kw-etio\">adénocarcinome</span> ou de lymphome</li><li>Si UD : pas de <span class=\"kw-ttt\">biopsie</span> de la <span class=\"kw-clinique\">lésion</span> duodénale</li></ul><h4>Suite</h4><ul><li>UG : <span class=\"kw-ttt\">IPP simple dose 4-8 sem</span> + <span class=\"kw-imagerie\">contrôle endoscopique systématique</span> avec biopsies de la zone cicatricielle</li><li>UD : <span class=\"kw-ttt\">IPP simple dose 4 sem</span> ; pas de contrôle endoscopique si asymptomatique</li><li>Si HP+ : éradication par <span class=\"kw-ttt\">quadrithérapie</span> (bismuthée si <span class=\"kw-ci\">allergie</span> β-lact, concomitante sinon), contrôle d'éradication systématique</li></ul><h4>Piège</h4><ul><li>Ulcère duodénal post-bulbaire (très rare) → évoquer <span class=\"kw-etio\">Zollinger-Ellison</span> ou <span class=\"kw-etio\">MICI</span>.</li></ul>"},{"id":"t-ipp-test","kind":"terminal","label":"IPP test 4 semaines + réévaluation","color":"green","detail":"<h4>Indication</h4><ul><li>Patient <span class=\"kw-chiffre\">&lt; 50 ans</span>, sans signe d'alarme, douleur ép<span class=\"kw-chiffre\">iga</span>strique évocatrice de <span class=\"kw-clinique\">syndrome ulcéreux</span> ou de <span class=\"kw-clinique\">RGO</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP simple dose pendant 4 semaines</span></li><li>Prise à jeun, le matin,<span class=\"kw-chiffre\"> 15-30 min</span> avant le repas</li><li><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> (arrêt <span class=\"kw-ttt\">AINS</span> si possible, arrêt tabac)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> clinique à<span class=\"kw-chiffre\"> 4 semaines</span> : si efficacité → arrêt ; si inefficacité ou récidive → <span class=\"kw-imagerie\">EOGD diagnostique</span> avec biopsies HP.</li></ul>"}]},"cards":[{"i":"17b213acbbc2","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les localisations préférentielles de l'ulcère duodénal ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">ulcère duodénal</span> se localise préférentiellement <strong>en plein <span class=\"nc-red nc-bold\">bulbe</span></strong> ou <strong>à la <span class=\"nc-red nc-bold\">pointe du bulbe</span></strong> (D1).</p></div>"},{"i":"3a0bd89b775e","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les localisations préférentielles de l'ulcère gastrique ?","a":"<div class=\"notion-course\"><p>L'ulcère gastrique se localise préférentiellement au niveau de l'<strong><span class=\"nc-red nc-bold\">antre</span></strong> et de <span class=\"nc-red nc-bold\">la </span><strong><span class=\"nc-red nc-bold\">petite courbure</span></strong>.</p></div>"},{"i":"5b8254608440","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelle est la définition physiopathologique de l'ulcère gastroduodénal ?","a":"<div class=\"notion-course\"><p>L'ulcère gastroduodénal (UGD) résulte d'un <strong>déséquilibre</strong> entre <span class=\"nc-gray_bg\">l'</span><strong><span class=\"nc-gray_bg\">agression chlorhydropeptique</span></strong> et les <strong><span class=\"nc-gray_bg\">mécanismes de défense</span> de la <span class=\"nc-purple nc-bold\">muqueuse</span></strong>, en un point précis de la paroi.</p></div>"},{"i":"68608d3ebaf3","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Comment différencier une érosion, une ulcération et un ulcère gastroduodénal selon la profondeur de l'atteinte ?","a":"<div class=\"notion-course\"><ul><li><strong>Érosion</strong> : limitée à la <strong>muqueuse</strong>.</li><li><strong>Ulcération</strong> : limitée à la <strong><span class=\"nc-purple nc-bold\">sous-muqueuse</span></strong>.</li><li><strong>Ulcère</strong> : atteint la <strong><span class=\"nc-red nc-bold\">musculeuse</span></strong>.</li></ul></div>"},{"i":"d6fa793486a6","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Qu'est-ce qui caractérise histologiquement un ulcère chronique par rapport à un ulcère aigu ?","a":"<div class=\"notion-course\"><p>L'ulcère chronique se distingue de l'ulcère aigu par l'existence d'un <strong>socle scléro-inflammatoire</strong> dans la <span class=\"nc-red nc-bold\">musculeuse</span>, contenant des hyperplasies nerveuses et des lésions d'endartérite.</p></div>"},{"i":"f946e5862d10","n":272,"o":"272-1","u":"Définition","t":"Connaître les définitions d'un ulcère gastrique ou duodénal","q":"Quelles sont les trois lignes de défense de la barrière muqueuse gastroduodénale ?","a":"<div class=\"notion-course\"><ul><li><strong>Pré-épithéliale</strong> : <span class=\"nc-green_bg\">mucus</span>, <span class=\"nc-pink nc-bold\">phospholipides</span> et bicarbonates.</li><li><strong>Épithéliale</strong> : <span class=\"nc-green_bg\">cellules de surface</span> assurant le <span class=\"nc-green_bg\">renouvellement cellulaire</span>.</li><li><strong>Sous-épithéliale</strong> : <span class=\"nc-pink nc-bold\">flux sanguin muqueux</span> (vascularisation).</li></ul></div>"},{"i":"65049b03bcfa","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelles sont les caractéristiques de la sténose, une complication de l'ulcère gastroduodénal ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">sténose</span> est une complication <strong>exceptionnelle</strong> de <span class=\"nc-pink nc-bold\">l'ulcère</span> gastroduodénal. Elle <span class=\"nc-orange nc-bold\">complique</span> les <strong><span class=\"nc-orange_bg\">ulcères</span> <span class=\"nc-orange_bg nc-bold\">bulbaires</span> et <span class=\"nc-orange_bg nc-bold\">pré-pyloriques</span></strong>. Cliniquement, elle se manifeste par des <strong>vomissements post-prandiaux <span class=\"nc-red nc-bold\">tardifs</span></strong>. Elle expose à un risque d'<strong><span class=\"nc-orange nc-bold\">alcalose métabolique</span> hypochlorémique hypokaliémique</strong>.</p></div>"},{"i":"a478b9faac23","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelle est la complication la plus fréquente de l'ulcère gastroduodénal et quelles sont ses caractéristiques ?","a":"<div class=\"notion-course\"><p>La complication la plus fréquente de l'ulcère gastroduodénal est l'<strong><span class=\"nc-red_bg\">hémorragie digestive</span></strong>. Elle est parfois inaugurale, représente <strong>30 à 40 % des hémorragies digestives hautes</strong>, et s'accompagne d'une mortalité d'environ <strong>10 %</strong>.</p></div>"},{"i":"e0c3660ebbaf","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Un ulcère gastroduodénal peut-il dégénérer en cancer ?","a":"<div class=\"notion-course\"><p>Oui, mais la <strong>dégénérescence</strong> ne concerne que l'<strong>ulcère gastrique</strong>. L'<span class=\"nc-red nc-bold\">ulcère duodénal</span> ne dégénère jamais.</p></div>"},{"i":"efb8c2b1a843","n":272,"o":"272-10","u":"Identifier une urgence","t":"Connaître les principales complications de l'ulcère","q":"Quelles sont les caractéristiques de la perforation, une complication de l'ulcère gastroduodénal ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">perforation</span> est une complication <strong>moins fréquente</strong> que l'hémorragie. Sa survenue est favorisée par la prise <span class=\"nc-orange_bg\">d'</span><strong><span class=\"nc-orange_bg\">AINS</span></strong>.</p></div>"},{"i":"226d06261071","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quels sont les pièges à éviter lors de l'évaluation initiale de la gravité d'une hématémèse ?","a":"<div class=\"notion-course\"><ul><li>La quantité de <strong>sang extériorisé</strong> est un <strong>mauvais critère de gravité</strong>.</li><li>Le taux d'<strong><span class=\"nc-brown_bg\">hémoglobine</span>/<span class=\"nc-brown_bg\">hématocrite</span></strong> peut <strong>sous-estimer</strong> initialement l'hémorragie.</li><li>Le sujet jeune peut <strong>compenser longtemps</strong> par une tachycardie.</li></ul></div>"},{"i":"40e2580548ba","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est l'orientation du patient et le rôle de l'endoscopie digestive haute (EOGD) en cas d'hématémèse ?","a":"<div class=\"notion-course\"><ul><li>Orientation selon saignement, hémodynamique, comorbidités et risque de récidive ; soins intensifs si instabilité ou haut risque. Endoscopie diagnostique et thérapeutique après <span class=\"nc-red nc-bold\">réanimation</span> initiale, habituellement dans les 24 <span class=\"nc-pink nc-bold\">heures</span> pour une hémorragie haute non variqueuse.</li><li>Saignement actif/<span class=\"nc-red nc-bold\">vaisseau visible</span> : hémostase ; <span class=\"nc-red nc-bold\">caillot adhérent</span> Forrest IIb : retrait puis <span class=\"nc-yellow_bg\">traitement</span> si compétence disponible selon ESGE 2026. Adrénaline seule insuffisante. Récidive : nouvelle hémostase puis embolisation/chirurgie selon échec.</li></ul></div>"},{"i":"745938002271","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est la prise en charge spécifique du choc hémorragique secondaire à une hématémèse ?","a":"<div class=\"notion-course\"><ul><li>Réanimation immédiate : voies veineuses, surveillance, cristalloïdes adaptés et produits sanguins selon pertes, perfusion et contexte. En hémorragie massive, ne pas attendre la baisse d’Hb ni l’échec du remplissage pour transfuser.</li><li>Hors hémorragie massive : stratégie restrictive, adaptée notamment aux cardiopathies. Vasopresseur si choc persistant selon équipe de <span class=\"nc-red nc-bold\">réanimation</span> ; contrôler rapidement le saignement.</li></ul></div>"},{"i":"a1a3e20067e9","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quels sont les signes d'évaluation de la gravité d'une hématémèse ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-blue_bg\">Hypotension</span>, <span class=\"nc-blue_bg\">tachycardie</span>, marbrures, temps de recoloration allongé, oligurie et altération de conscience. Une <span class=\"nc-blue_bg\">bradycardie</span> peut accompagner une situation extrême.</li><li>Une fréquence normale sous bêtabloquant ou une Hb initialement normale n’excluent pas la gravité ; les seuils adultes ne sont pas transposables tels quels à l’enfant.</li></ul></div>"},{"i":"b6c0d085cdf6","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelle est la stratégie de traitement par IPP après une hémorragie digestive haute en fonction des stades de Forrest ?","a":"<div class=\"notion-course\"><ul><li>Après hémostase d’un ulcère à haut risque : <span class=\"nc-yellow_bg nc-bold\">IPP</span> à forte dose pendant 72 <span class=\"nc-pink nc-bold\">heures</span> selon schéma IV continu ou intermittent/oral validé, puis relais oral.</li><li>Forrest IIc/III à faible risque : <span class=\"nc-yellow_bg nc-bold\">IPP</span> oral, sans imposer une perfusion continue. Adapter durée totale à l’ulcère et à sa cause.</li></ul></div>"},{"i":"d30f37f070ab","n":272,"o":"272-11","u":"Identifier une urgence","t":"Connaître la stratégie à adopter devant une hématémèse","q":"Quelles sont les premières mesures à adopter devant une hématémèse, avant l'endoscopie ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-purple_bg\">Hématémèse</span>, <span class=\"nc-purple_bg\">méléna</span> ou rectorragie abondante : évaluer immédiatement circulation, conscience et perfusion ; une Hb initiale normale n’exclut pas une <span class=\"nc-red nc-bold\">hémorragie</span> grave. Voies veineuses, bilan transfusionnel et <span class=\"nc-red nc-bold\">réanimation</span> adaptée.</li><li>Transfusion généralement restrictive, modulée par saignement actif et terrain cardiovasculaire. Réévaluer anticoagulants et antiagrégants selon gravité et risque thrombotique ; pas d’arrêt ou de neutralisation indifférencié.</li><li>Endoscopie après réanimation initiale, généralement dans les 24 <span class=\"nc-pink nc-bold\">heures</span> pour une hémorragie haute non variqueuse. Hémostase des saignements actifs et vaisseaux visibles ; adrénaline jamais utilisée seule comme <span class=\"nc-yellow_bg\">traitement</span> définitif.</li></ul></div>"},{"i":"4ed8e78839e7","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quel est l'examen paraclinique de première intention en cas de suspicion de perforation d'un ulcère gastroduodénal en péritoine libre ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">L'examen</span> de première intention en cas de suspicion de <span class=\"nc-orange_bg\">perforation</span> d'un ulcère gastroduodénal en péritoine libre est une <strong>TDM abdomino-pelvienne injectée</strong>.</p><p>Cet examen objective un <strong><span class=\"nc-red nc-bold\">pneumopéritoine</span></strong> et une réaction inflammatoire antro-pyloro-bulbaire. L'<strong>endoscopie est formellement contre-indiquée</strong>.</p></div>"},{"i":"89988820ea8a","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quels sont les signes cliniques évoquant une perforation d'un ulcère gastroduodénal en péritoine libre ?","a":"<div class=\"notion-course\"><p>La perforation d'un ulcère gastroduodénal en péritoine libre se manifeste par :</p><ul><li>Une <span class=\"nc-yellow_bg\">douleur</span> <span class=\"nc-yellow_bg nc-bold\">épigastrique</span> en <strong>coup de poignard</strong>, d'apparition <strong>brutale</strong>, diffusant rapidement à l'ensemble de l'abdomen.</li><li>Une <strong><span class=\"nc-orange nc-bold\">contracture abdominale</span></strong> (« ventre de bois »).</li><li>Un Douglas douloureux au toucher rectal.</li><li>Des <span class=\"nc-red_bg\">signes de choc</span>.</li><li>Un tympanisme à la percussion et une <strong>disparition de la matité préhépatique</strong> (signe de <span class=\"nc-red nc-bold\">pneumopéritoine</span>, quasi-pathognomonique).</li><li>Initialement, l'absence de fièvre et d'hyperleucocytose (péritonite chimique).</li></ul></div>"},{"i":"901cddd97878","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Comment différencier une perforation en péritoine libre d'un ulcère gastroduodénal et un ulcère perforé-bouché ?","a":"<div class=\"notion-course\"><p>La perforation en péritoine libre se caractérise par :</p><ul><li>Une douleur initiale en <strong>coup de poignard</strong>.</li><li>Un <strong><span class=\"nc-red nc-bold\">pneumopéritoine</span></strong> (disparition de la matité préhépatique à <span class=\"nc-blue nc-bold\">l'examen</span> clinique et air libre sous-diaphragmatique à la TDM).</li></ul><p>L'ulcère perforé-bouché (perforation au contact du <span class=\"nc-purple_bg\">pancréas</span>) se distingue par :</p><ul><li>Une <strong>régression de la douleur initiale</strong>.</li><li>L'absence de pneumopéritoine (un rétro-pneumopéritoine est possible).</li></ul></div>"},{"i":"9da9dacf25d4","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quelle est la prise en charge spécifique d'un ulcère perforé-bouché stable, sans signe de gravité ?","a":"<div class=\"notion-course\"><p>En l'absence de <span class=\"nc-red nc-bold\">signes de gravité</span>, un ulcère perforé-bouché peut être géré selon la <strong>méthode de Taylor</strong>. Cette méthode consiste en :</p><ul><li>La pose d'une <strong>sonde naso-gastrique en <span class=\"nc-pink nc-bold\">aspiration</span></strong>.</li><li>L'administration d'<strong>inhibiteurs de la pompe à protons (IPP)</strong>.</li><li>Une <strong>antibiothérapie</strong> adaptée.</li></ul></div>"},{"i":"eccc65fa8665","n":272,"o":"272-12","u":"Identifier une urgence","t":"Connaître les mesures à mettre en œuvre dans les formes perforées","q":"Quelle est la prise en charge thérapeutique initiale d'une perforation d'ulcère gastroduodénal en péritoine libre ?","a":"<div class=\"notion-course\"><p>La perforation d'ulcère gastroduodénal en péritoine libre est une <strong>urgence chirurgicale</strong>. Elle impose une prise en charge de péritonite secondaire incluant, en plus de la chirurgie, une <strong>antibiothérapie probabiliste</strong>.</p></div>"},{"i":"154720927caa","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quelle est la stratégie en cas d'échec de la première ligne de traitement d'éradication d'Helicobacter pylori ?","a":"<div class=\"notion-course\"><ul><li>Après échec d’un <span class=\"nc-yellow_bg\">traitement</span> probabiliste : vérifier observance, doses et conditions du contrôle, puis utiliser l’autre quadrithérapie recommandée selon antécédents et contre-indications.</li><li>Après deux échecs : endoscopie avec biopsies pour étude de sensibilité et stratégie guidée. Une indication <span class=\"nc-blue_bg\">endoscopique</span> indépendante peut imposer de la réaliser plus tôt.</li></ul></div>"},{"i":"4f57b31ce06d","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment traite-t-on un ulcère gastrique non compliqué ?","a":"<div class=\"notion-course\"><p>Un ulcère <span class=\"nc-pink_bg\">gastrique</span> <span class=\"nc-pink nc-bold\">non compliqué</span> se traite par un <strong>inhibiteur de la pompe à protons (IPP) simple dose</strong> pendant <strong>4 à <span class=\"nc-pink nc-bold\">8 semaines</span></strong>. Ce <span class=\"nc-yellow_bg\">traitement</span> doit impérativement être suivi d'un <strong>contrôle <span class=\"nc-blue nc-bold\">endoscopique</span></strong> de la <span class=\"nc-green_bg nc-bold\">cicatrisation</span> avec <span class=\"nc-blue nc-bold\">biopsies</span>.</p></div>"},{"i":"531a847d71c0","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment gère-t-on un ulcère gastroduodénal associé à Helicobacter pylori (HP) ?","a":"<div class=\"notion-course\"><ul><li>Associer cicatrisation par IPP et éradication par le schéma guidé ou probabiliste adapté, puis prouver l’éradication. La durée des antibiotiques dépend du schéma (dix ou quatorze jours).</li><li>Poursuite des <span class=\"nc-yellow_bg nc-bold\">IPP</span> selon siège, complication, <span class=\"nc-green_bg nc-bold\">cicatrisation</span> et médicaments à risque ; un <span class=\"nc-red nc-bold\">ulcère gastrique</span> nécessite un contrôle <span class=\"nc-blue nc-bold\">endoscopique</span>. Pas d’<span class=\"nc-yellow_bg nc-bold\">IPP</span> indéfini pour le seul antécédent d’<span class=\"nc-red nc-bold\">ulcère duodénal</span> guéri après éradication.</li></ul></div>"},{"i":"60b29ba0de21","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Comment doit être réalisé le contrôle de l'éradication d'Helicobacter pylori après traitement ?","a":"<div class=\"notion-course\"><ul><li>Vérifier <span class=\"nc-green nc-bold\">l’éradication</span> par test respiratoire au moins quatre <span class=\"nc-pink nc-bold\">semaines</span> après les antibiotiques et après au moins deux <span class=\"nc-pink nc-bold\">semaines</span> sans <span class=\"nc-pink nc-bold\">IPP</span>. Adapter la poursuite des <span class=\"nc-pink nc-bold\">IPP</span> à <span class=\"nc-pink nc-bold\">l’ulcère</span>, sa complication et sa <span class=\"nc-green_bg nc-bold\">cicatrisation</span> ; contrôle <span class=\"nc-blue nc-bold\">endoscopique</span> d’un ulcère gastrique.</li></ul></div>"},{"i":"9654c8aefb25","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quels sont les principaux schémas d'éradication d'Helicobacter pylori et leurs indications ?","a":"<div class=\"notion-course\"><ul><li>Sans sensibilité connue : quadrithérapie bismuthée dix jours ou concomitante (<span class=\"nc-green_bg\">IPP</span>, <span class=\"nc-pink_bg\">amoxicilline</span>, <span class=\"nc-pink_bg\">clarithromycine</span>, métronidazole) quatorze jours selon HAS et terrain.</li><li>Traitement guidé dix jours : <span class=\"nc-green_bg\">IPP</span> + <span class=\"nc-pink_bg\">amoxicilline</span> + <span class=\"nc-pink_bg\">clarithromycine</span> si sensible ; <span class=\"nc-pink_bg\">lévofloxacine</span> si résistante à la <span class=\"nc-pink_bg\">clarithromycine</span> et sensible à la <span class=\"nc-pink_bg\">lévofloxacine</span>. Résistance aux deux : quadrithérapie bismuthée. Cette trithérapie guidée ne se nomme pas « concomitante ».</li></ul></div>"},{"i":"fcac2982c1b1","n":272,"o":"272-15","u":"Prise en charge","t":"Connaître les principes du traitement de l'ulcère non compliqué, y compris celui de l'éradication de l'HP","q":"Quels sont les objectifs du traitement de l'ulcère gastroduodénal (UGD) non compliqué ?","a":"<div class=\"notion-course\"><p>Les objectifs du traitement de l'UGD <span class=\"nc-pink nc-bold\">non compliqué</span> sont :</p><ul><li>Suppression rapide des symptômes.</li><li>Cicatrisation de l'ulcère.</li><li>Prévention des récidives.</li><li>Prévention des complications.</li></ul></div>"},{"i":"4b0e12070007","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Comment poser le diagnostic histologique de la gastrite ?","a":"<div class=\"notion-course\"><p>Le diagnostic histologique de <span class=\"nc-yellow_bg\">gastrite</span> nécessite de réaliser <strong>5 <span class=\"nc-blue_bg\">biopsies</span></strong> lors de l'<span class=\"nc-blue_bg\">endoscopie</span> :</p><ul><li><strong>2 au niveau du fundus</strong></li><li><strong>2 au niveau de l'antre gastrique</strong></li><li><strong>1 au niveau de l'angle de <span class=\"nc-red nc-bold\">la petite courbure</span></strong></li></ul></div>"},{"i":"6cc25d85a7f6","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Comment distinguer une gastrite d'une gastropathie ?","a":"<div class=\"notion-course\"><p>La <strong><span class=\"nc-yellow_bg\">gastrite</span></strong> est caractérisée par un <strong>infiltrat inflammatoire</strong> de la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique. La <strong><span class=\"nc-yellow_bg\">gastropathie</span></strong> est une affection diffuse de la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique, mais <strong><span class=\"nc-pink nc-bold\">sans infiltrat inflammatoire</span></strong>.</p></div>"},{"i":"91d990086d73","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Quelle est la particularité de la corrélation entre les signes cliniques, l'aspect endoscopique et l'histologie d'une gastrite ?","a":"<div class=\"notion-course\"><p><span class=\"nc-brown_bg\">Il n'existe</span> <strong>aucune corrélation</strong> entre l'histologie d'une <span class=\"nc-yellow_bg\">gastrite</span> et la <span class=\"nc-red nc-bold\">symptomatologie</span> clinique ou l'aspect endoscopique. Le terme « <span class=\"nc-yellow_bg\">gastrite</span> » est un <strong>diagnostic purement histologique</strong>.</p></div>"},{"i":"9a6c0c064687","n":272,"o":"272-16","u":"Définition","t":"Connaître la définition d'une gastrite","q":"Quelle est la définition histologique d'une gastrite ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-yellow_bg\">gastrite</span> est définie histologiquement par des <strong>lésions inflammatoires aiguës ou chroniques de la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique</strong>.</p></div>"},{"i":"0d24654e9aed","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Quelles sont les caractéristiques de la douleur typique de l'ulcère gastroduodénal et comment évolue-t-elle au cours de la journée ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-yellow_bg\">douleur</span> typique de l'ulcère gastroduodénal est <strong><span class=\"nc-yellow_bg nc-bold\">épigastrique</span></strong>, <span class=\"nc-yellow_bg\">à type de</span> <strong><span class=\"nc-yellow_bg nc-bold\">crampe</span></strong>, de <strong><span class=\"nc-yellow_bg nc-bold\">torsion</span></strong> <span class=\"nc-yellow_bg\">ou de</span> <strong><span class=\"nc-yellow_bg nc-bold\">faim douloureuse</span></strong>.</p><ul><li>Elle est <strong><span class=\"nc-green_bg\">calmée par la prise d'aliments</span></strong>, d'anti-acides et de pansements gastriques.</li><li>Elle présente une <strong>périodicité diurne</strong> : <span class=\"nc-yellow_bg\">douleur</span> <strong><span class=\"nc-red nc-bold\">post-prandiale tardive</span></strong>, survenant 1 à 3 <span class=\"nc-pink nc-bold\">heures</span> après les repas.</li></ul></div>"},{"i":"c23c82fe8a81","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Quelles sont les particularités et pièges du syndrome douloureux atypique de l'ulcère gastroduodénal ?","a":"<div class=\"notion-course\"><p>Le syndrome douloureux atypique de l'ulcère gastroduodénal peut présenter :</p><ul><li>Une <strong>localisation variable</strong> (<span class=\"nc-blue_bg\">hypochondre</span> <span class=\"nc-blue_bg nc-bold\">droit</span>, <span class=\"nc-blue_bg nc-bold\">gauche</span>, <span class=\"nc-blue_bg\">irradiation</span> <span class=\"nc-blue_bg nc-bold\">dorsale</span> ou strictement postérieure).</li><li>Une <strong>intensité variable</strong> (forme hyperalgique pseudo-chirurgicale ou simple gêne frustre).</li><li>Une <strong>absence de périodicité</strong>, la <span class=\"nc-yellow_bg\">douleur</span> n'est pas rythmée par l'alimentation.</li></ul><p>Le piège est que le <strong>syndrome douloureux atypique est plus <span class=\"nc-red nc-bold\">fréquent</span> que la forme typique</strong>.</p></div>"},{"i":"db44a2185abc","n":272,"o":"272-6","u":"Diagnostic positif","t":"Connaître les caractéristiques/sémiologie de la douleur de l'ulcère","q":"Comment la douleur typique de l'ulcère gastroduodénal évolue-t-elle au cours de l'année ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-yellow_bg\">douleur</span> typique de l'ulcère gastroduodénal présente une <strong>double périodicité</strong>, incluant une périodicité annuelle :</p><ul><li>Elle se manifeste par des <strong><span class=\"nc-red_bg\">poussées</span> de quelques <span class=\"nc-pink nc-bold\">semaines</span></strong>.</li><li>Ces <span class=\"nc-red_bg\">poussées</span> sont séparées par des <strong>intervalles asymptomatiques</strong> de quelques <span class=\"nc-pink nc-bold\">mois</span> à plusieurs <span class=\"nc-pink nc-bold\">années</span>.</li></ul></div>"},{"i":"7a0e34d98e86","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Pourquoi la réalisation d'une endoscopie digestive haute (EOGD) est-elle indispensable pour diagnostiquer un ulcère gastroduodénal ?","a":"<div class=\"notion-course\"><p>L'EOGD est indispensable car :</p><ul><li>Elle <strong>affirme le diagnostic</strong> d'ulcère, qui ne peut pas reposer uniquement sur les symptômes.</li><li>Elle permet d'<strong>éliminer les diagnostics différentiels</strong>, notamment un <strong>cancer</strong> en cas d'ulcère gastrique.</li><li>Elle offre la possibilité de réaliser des <strong>biopsies</strong> en cas de nécessité.</li></ul></div>"},{"i":"8a70d6a3998c","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quelles sont les indications de l'endoscopie digestive haute (EOGD) chez un patient présentant une douleur ulcéreuse ?","a":"<div class=\"notion-course\"><p>Une EOGD est indiquée devant une douleur ulcéreuse dans les cas suivants :</p><ul><li>Âge <strong>supérieur à 50 ans</strong>.</li><li>Présence de <strong><span class=\"nc-red nc-bold\">signes d'alarme</span></strong> : <span class=\"nc-red_bg\">dysphagie</span>, <span class=\"nc-red_bg\">amaigrissement</span>, <span class=\"nc-red_bg\">hémorragie digestive</span>, <span class=\"nc-red_bg\">anémie</span>.</li><li><strong>Inefficacité du traitement symptomatique de première intention</strong>.</li></ul></div>"},{"i":"9a3246b5894a","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quelle est la particularité de la conduite à tenir biopsique et du suivi endoscopique entre un ulcère duodénal et un ulcère gastrique ?","a":"<div class=\"notion-course\"><p>La conduite à tenir diffère selon le siège :</p><ul><li><strong><span class=\"nc-red nc-bold\">Ulcère duodénal</span></strong> : <strong>pas de biopsie</strong> de la lésion duodénale elle-même. Des <span class=\"nc-yellow_bg\">biopsies gastriques (antre, angle, fundus)</span> sont réalisées pour rechercher <em><span class=\"nc-red_bg\">Helicobacter pylori</span></em>. Le contrôle <span class=\"nc-blue nc-bold\">endoscopique</span> <span class=\"nc-green_bg\">n'est</span> pas <span class=\"nc-red nc-bold\">systématique</span> si le patient est <span class=\"nc-green_bg\">asymptomatique</span>, sauf en cas d'<span class=\"nc-red nc-bold\">ulcère duodénal</span> <span class=\"nc-orange nc-bold\">compliqué</span>.</li><li><strong>Ulcère <span class=\"nc-pink_bg\">gastrique</span></strong> : biopsies <strong>systématiques des berges de <span class=\"nc-pink nc-bold\">l'ulcère</span></strong> (<strong>6 à 12 biopsies</strong>) pour rechercher un <span class=\"nc-red nc-bold\">adénocarcinome</span> ou un <span class=\"nc-red nc-bold\">lymphome</span>, en plus des biopsies <span class=\"nc-yellow_bg\">gastriques</span> pour <em><span class=\"nc-pink_bg\">H. pylori</span></em>. Une <strong>fibroscopie de contrôle</strong> est nécessaire après traitement.</li></ul><p>Dans <strong>tout ulcère gastroduodénal</strong>, la recherche de <em><span class=\"nc-pink_bg\">H. pylori</span></em> est <strong>systématique</strong>.</p></div>"},{"i":"b41fa92c6d66","n":272,"o":"272-7","u":"Examens complémentaires","t":"Connaître les indications de l'endoscopie haute devant une douleur ulcéreuse","q":"Quel aspect endoscopique est caractéristique d'un ulcère gastroduodénal et quel piège diagnostique doit être connu ?","a":"<div class=\"notion-course\"><p>L'aspect endoscopique typique d'un ulcère est :</p><ul><li>Une <strong>perte de substance profonde « <span class=\"nc-red nc-bold\">creusante</span> »</strong>.</li><li>Un <span class=\"nc-brown_bg\">fond </span><strong><span class=\"nc-brown_bg\">pseudo-membraneux</span> blanchâtre</strong>, parfois <span class=\"nc-red nc-bold\">nécrotique</span>.</li><li>Une lésion <strong><span class=\"nc-brown_bg\">ronde</span> ou <span class=\"nc-brown_bg\">ovalaire</span></strong>, à <span class=\"nc-brown_bg\">bords </span><strong><span class=\"nc-brown_bg\">réguliers</span>, surélevés et érythémateux</strong>.</li></ul><p>Un <strong><span class=\"nc-red nc-bold\">ulcère duodénal</span> post-bulbaire</strong> (très rare) doit faire évoquer un <strong>syndrome de <span class=\"nc-red nc-bold\">Zollinger-Ellison</span></strong> ou une <strong>MICI</strong> (<span class=\"nc-orange_bg\">Maladie de Crohn</span>, <span class=\"nc-red_bg\">vascularite</span>).</p></div>"},{"i":"08801bfb4b41","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Quel est le piège classique à éviter concernant les biopsies pour la recherche d'Helicobacter pylori, notamment dans le contexte d'un ulcère hémorragique ?","a":"<div class=\"notion-course\"><ul><li>Pour H. pylori, prélèvements <span class=\"nc-yellow_bg\">gastriques</span> antraux et <span class=\"nc-yellow_bg nc-bold\">fundiques</span> adaptés. Une hémorragie n’interdit pas systématiquement toute biopsie : juger la sécurité du geste.</li><li>Saignement et traitements peuvent diminuer la sensibilité ; recontrôler un test négatif si nécessaire. La sérologie ne permet pas le contrôle d’éradication.</li></ul></div>"},{"i":"78554b27b1d0","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Dans quel contexte clinique doit-on systématiquement rechercher Helicobacter pylori (HP) d'après le contenu source ?","a":"<div class=\"notion-course\"><p>La recherche d'<i><span class=\"nc-pink_bg\">H. pylori</span></i> est systématique devant :</p><ul><li>Tout <strong>ulcère gastroduodénal (UGD)</strong>.</li><li>Tout <strong>cancer de l'estomac</strong>.</li><li>Des <strong>facteurs de risque</strong> de <span class=\"nc-red nc-bold\">cancer gastrique</span> (apparenté du 1er degré, syndrome de Lynch (HNPCC), ATCD de <span class=\"nc-pink_bg\">gastrectomie partielle</span>, lésions prénéoplasiques : <span class=\"nc-red\">atrophie</span> sévère, <span class=\"nc-red nc-bold\">métaplasie intestinale</span>, <span class=\"nc-red\">dysplasie</span>).</li></ul></div>"},{"i":"ad6f765767a5","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Quels sont les tests invasifs et non invasifs pour la recherche d'Helicobacter pylori, et leurs principales caractéristiques ou indications spécifiques (selon le contenu) ?","a":"<div class=\"notion-course\"><ul><li>Si endoscopie indiquée : biopsies <span class=\"nc-yellow_bg\">gastriques</span> pour histologie et recherche de H. pylori, avec culture/<span class=\"nc-blue nc-bold\">antibiogramme</span> ou <span class=\"nc-blue\">PCR</span> de résistance selon disponibilité.</li><li>Tests non invasifs : test respiratoire à l’urée et <span class=\"nc-red_bg\">antigènes fécaux</span> adaptés ; sérologie dans certaines situations, mais ni preuve d’infection <span class=\"nc-red nc-bold\">active</span> après <span class=\"nc-yellow_bg\">traitement</span> ni contrôle d’éradication. Les performances dépendent du contexte, notamment <span class=\"nc-yellow_bg nc-bold\">IPP</span>, antibiotiques et saignement.</li></ul></div>"},{"i":"ca622937dcaa","n":272,"o":"272-8","u":"Examens complémentaires","t":"Savoir prescrire une recherche d'HP (tests invasifs et non invasifs)","q":"Selon la HAS, en dehors des situations systématiques, dans quelles autres situations spécifiques la recherche d'Helicobacter pylori est-elle recommandée ?","a":"<div class=\"notion-course\"><p>La HAS recommande la recherche d'<i><span class=\"nc-pink_bg\">H. pylori</span></i> avant de débuter un traitement par <strong>AINS</strong> ou <strong><span class=\"nc-pink nc-bold\">aspirine</span></strong> si le patient a des antécédents d'UGD, et en cas de :</p><ul><li><span class=\"nc-orange_bg\">Carence martiale</span> <strong><span class=\"nc-orange_bg\">inexpliquée</span></strong>.</li><li><span class=\"nc-orange_bg\">Carence en </span><strong><span class=\"nc-orange_bg\">B12</span></strong> sans cause identifiée.</li><li><span class=\"nc-orange_bg\">Lymphome</span> <span class=\"nc-pink_bg\">gastrique</span> du <strong><span class=\"nc-orange_bg\">MALT</span></strong>.</li><li><span class=\"nc-pink_bg\">Avant</span> un <strong><span class=\"nc-pink_bg\">by-pass</span> <span class=\"nc-pink_bg\">gastrique</span></strong>.</li><li>Purpura thrombopénique immunologique (PTI) de l'adulte.</li></ul></div>"},{"i":"35d129560508","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quelle est l'importance de l'intensité de la douleur ulcéreuse pour juger de sa gravité ?","a":"<div class=\"notion-course\"><p>L'intensité de la douleur ulcéreuse n'a <strong>aucun caractère prédictif de gravité</strong> et l'on ne retrouve <span class=\"nc-brown_bg nc-bold\">pas de parallélisme anatomo-clinique</span>. <span class=\"nc-brown_bg\">Il n'existe</span> <strong>aucun critère de gravité de la douleur ulcéreuse elle-même</strong>.</p></div>"},{"i":"6bbd636e3d9b","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une éventuelle dégénérescence en cancer chez un patient présentant une douleur ulcéreuse ?","a":"<div class=\"notion-course\"><p>Devant une douleur ulcéreuse, l'existence d'un <strong><span class=\"nc-red_bg\">amaigrissement</span></strong> ou d'une <strong>adénopathie sus-claviculaire</strong> (ganglion de Troisier) doit faire suspecter et rechercher une dégénérescence en <span class=\"nc-red nc-bold\">cancer</span>.</p></div>"},{"i":"9bc169064e4d","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une perforation dans le contexte d'une douleur ulcéreuse ?","a":"<div class=\"notion-course\"><p>Face à une douleur ulcéreuse, la présence d'une <strong>défense</strong> ou d'une <strong><span class=\"nc-orange nc-bold\">contracture abdominale</span></strong> doit faire évoquer et rechercher une <span class=\"nc-red nc-bold\">perforation</span>.</p></div>"},{"i":"f62a036e5a6c","n":272,"o":"272-9","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d'une douleur ulcéreuse","q":"Quels sont les signes cliniques qui doivent faire rechercher une hémorragie digestive dans le contexte d'une douleur ulcéreuse ?","a":"<div class=\"notion-course\"><p>En présence d'une douleur ulcéreuse, l'apparition des signes suivants doit faire rechercher une <span class=\"nc-red nc-bold\">hémorragie</span> :</p><ul><li><strong>Chute tensionnelle</strong></li><li><strong>Tachycardie</strong></li><li><strong><span class=\"nc-purple_bg\">Hématémèse</span></strong> ou <strong><span class=\"nc-purple_bg\">méléna</span></strong></li><li>Présence de <strong>sang au toucher rectal</strong></li></ul></div>"},{"i":"b9624daf7435","n":272,"o":"272-2","u":"Epidémiologie","t":"Connaître la prévalence de l'ulcère gastrique ou duodénal","q":"Quels sont les points essentiels concernant la prévalence de l'ulcère gastrique ou duodénal ?","a":"<div class=\"notion-course\"><p>L'<span>incidence</span> de l'<span>UGD</span> est en <strong>régression</strong> dans <span>les</span> pays développés, parallèlement au <span class=\"nc-green_bg\">recul de l'infection gastrique à </span><span><span class=\"nc-green_bg\">H. pylori</span></span>.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><span>Incidence</span></td><td>Pays développés <span>1 à 2 / 1000 / an</span> ; France <span>≈ 90 000 cas/an</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance <span class=\"nc-pink_bg\">masculine</span> <span><span class=\"nc-pink nc-bold\">2 H / 1 F</span></span> (LISA) ; l'ancien référentiel ne retrouvait cette prédominance que pour l'<strong><span class=\"nc-red nc-bold\">ulcère duodénal</span></strong></td></tr>\n          <tr><td>Âge</td><td><span class=\"nc-pink_bg\">Avant </span><span><span class=\"nc-pink_bg\">55 ans</span></span>, l'<span class=\"nc-red nc-bold\">ulcère duodénal</span> est <span>3 à 4×</span> plus fréquent que l'ulcère gastrique</td></tr>\n          <tr><td><span>Terrain</span></td><td>Patients avec <span>comorbidités</span> cardiovasculaire, rénale, hépatique ou pancréatique ; <span>les</span> ulcères du <span>sujet âgé</span> sont volontiers <span class=\"nc-red nc-bold\">compliqués</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Mortalité</span></strong> — le taux de mortalité des complications ulcéreuses (hémorragie, <span>comorbidités</span> associées) est de <span>2 à 10 %</span>. Un <span>tiers</span> des <span><span class=\"nc-orange_bg\">UGD</span></span><span class=\"nc-orange_bg\"> compliqués</span> est attribuable aux <span><span class=\"nc-pink_bg\">AINS</span></span> ou à l'<span><span class=\"nc-pink nc-bold\">aspirine</span> à faible dose</span>.</p></div>"},{"i":"99767f572fd2","n":272,"o":"272-3","u":"Physiopathologie","t":"Connaître le mécanisme des ulcères hémorragiques","q":"Quels sont les points essentiels concernant le mécanisme des ulcères hémorragiques ?","a":"<div class=\"notion-course\"><p>L'hémorragie résulte de l'<span><span class=\"nc-yellow_bg\">ulcération des vaisseaux de la paroi gastroduodénale</span></span><span class=\"nc-yellow_bg\">.</span> En cas d'hémorragie <span>sévère</span>, il s'agit le plus souvent de l'<span>érosion</span> d'une artère, dont le siège dépend de la localisation de l'ulcère :</p>\n      <table>\n        <thead><tr><th>Siège de l'ulcère</th><th>Artère érodée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Face postérieure du bulbe duodénal</span></td><td><span><span class=\"nc-pink nc-bold\">Artère gastro-duodénale</span></span></td></tr>\n          <tr><td><span class=\"nc-red_bg\">Petite courbure gastrique</span></td><td><span><span class=\"nc-pink nc-bold\">Artère gastrique gauche</span></span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier — <span>ulcération</span> de Dieulafoy :</strong> <span>ulcération <span class=\"nc-purple nc-bold\">muqueuse</span> en regard d'une artère <span class=\"nc-purple nc-bold\">sous-muqueuse</span> volumineuse</span>. Le diagnostic est difficile car l'artère n'est pas toujours apparente et le <span>saignement abondant</span> gêne le geste d'hémostase.</p>\n      <p><strong><span>Classification</span> de Forrest</strong> <span>(Rang B)</span> — décrit l'aspect endoscopique de l'<span class=\"nc-red nc-bold\">ulcère </span><span><span class=\"nc-red nc-bold\">hémorragique</span></span> ; elle est <strong>corrélée au risque de récidive hémorragique</strong> :</p>\n      <table>\n        <thead><tr><th><span>Stade</span></th><th>Aspect endoscopique</th></tr></thead>\n        <tbody>\n          <tr><td>I a</td><td><span>Hémorragie en jet</span></td></tr>\n          <tr><td>I b</td><td>Suintement diffus</td></tr>\n          <tr><td>II a</td><td><span class=\"nc-red nc-bold\">Vaisseau visible</span>, non <span>hémorragique</span></td></tr>\n          <tr><td>II b</td><td><span class=\"nc-red nc-bold\">Caillot adhérent</span></td></tr>\n          <tr><td>II c</td><td>Taches p<span>igm</span>entées</td></tr>\n          <tr><td>III</td><td>Cratère à fond propre</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 355 — <span class=\"nc-red_bg\">Hémorragie digestive</span></em></p></div>"},{"i":"d8e415d67382","n":272,"o":"272-4","u":"Physiopathologie","t":"Connaître les facteurs favorisants des formes compliquées des ulcères gastrique ou duodénal","q":"Quels sont les points essentiels concernant les facteurs favorisants des formes compliquées des ulcères gastrique ou duodénal ?","a":"<div class=\"notion-course\"><p><strong><span>Facteurs de risque</span> des ulcères <span class=\"nc-red nc-bold\">compliqués</span></strong> — ils prédisposent à l'hémorragie et à la perforation :</p>\n      <ul>\n        <li><span>Âge &gt; 65 ans</span></li>\n        <li><span><span class=\"nc-orange nc-bold\">ATCD d'UGD</span> compliqué</span></li>\n        <li><span><span class=\"nc-brown_bg\">AINS</span></span> ou <span><span class=\"nc-brown_bg\">aspirine</span></span>, particulièrement en cas <span class=\"nc-brown_bg\">d'</span><span><span class=\"nc-brown_bg\">infection à H. pylori</span></span> associée</li>\n        <li><span class=\"nc-brown_bg\">Prise d'</span><span><span class=\"nc-brown_bg\">anticoagulant</span></span></li>\n      </ul>\n      <p><strong><span><span class=\"nc-pink_bg\">AINS</span></span> et <span>aspirine</span></strong> — l'<span>inhibition de la COX-1</span> (qui produit <span>les</span> prostaglandines gastroduodénales) favorise les <span>UGD</span> (plutôt <strong>gastriques</strong>) et leurs complications :</p>\n      <ul>\n        <li><span>AINS</span> : risque relatif <span>≈ 4</span></li>\n        <li><span><span class=\"nc-pink nc-bold\">Aspirine</span></span> : risque relatif <span>≈ 1,5</span> ; à dose anti-agrégante, elle ajoute une <span><span class=\"nc-red nc-bold\">gastrotoxicité directe</span></span> et expose au <span>risque hémorragique</span></li>\n        <li><span>Coxibs</span> (anti-COX-2 préservant la COX-1) : réduisent le risque de complications de <span>≈ 50 %</span> <span class=\"nc-red_bg\">sans le supprimer</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">Les <span class=\"nc-orange nc-bold\">corticoïdes</span> ne justifient pas à eux seuls une gastroprotection <span class=\"nc-red nc-bold\">systématique</span> ; le risque digestif dépend du terrain et augmente notamment avec les <span class=\"nc-brown_bg\">AINS</span>.</div>\n      <p><strong><span>Syndrome de <span class=\"nc-red nc-bold\">Zollinger</span></span><span class=\"nc-red nc-bold\">-Ellison</span></strong> <span>(rare)</span> — hypersécrétion acide liée à une <span>hypergastrinémie tumorale</span> (<span class=\"nc-yellow_bg\">gastrinome</span>, tumeur neuro-endocrine pancréatico-duodénale, <span>maligne dans 50-60 %</span>) ; <span>sporadique dans 75 %</span> des cas, ou associé à une <span>NEM1</span>. Tableau : ulcères <span><span class=\"nc-red nc-bold\">multiples</span>, <span class=\"nc-red nc-bold\">récidivants</span>, souvent <span class=\"nc-red nc-bold\">compliqués</span></span> + <span><span class=\"nc-red_bg\">diarrhée chronique</span> <span class=\"nc-blue nc-bold\">sécrétoire</span></span> améliorée sous <span><span class=\"nc-yellow_bg nc-bold\">IPP</span></span>.</p>\n      <p><strong>Autres facteurs d'agression</strong> (à rechercher devant un ulcère non lié à HP ni aux <span><span class=\"nc-brown_bg nc-bold\">AINS</span></span>) :</p>\n      <ul>\n        <li><span>Tabac</span></li>\n        <li><span><span class=\"nc-orange_bg\">Maladie de Crohn</span></span>, <span><span class=\"nc-orange_bg\">vascularites</span></span></li>\n        <li>Infections chez l'immunodéprimé : <span><span class=\"nc-purple_bg nc-bold\">tuberculose</span></span>, <span><span class=\"nc-purple_bg nc-bold\">CMV</span></span></li>\n        <li><span><span class=\"nc-orange_bg\">Stress pathologique intense</span></span> : <span>réanimation</span>, grand brûlé</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pièges pertinents — </strong>ne sont <span>PAS</span> des <span>facteurs de risque</span> d'<span><span class=\"nc-blue_bg\">UGD</span></span> : l'<span>alcool</span>, le <span>régime alimentaire</span>, le <span>stress psychologique</span>. L'<span>alcool</span> est cependant pourvoyeur de gastropathie chimique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span>surveillance</span> des médicaments - hors anti-<span>infectieux</span> · 282 — <span>MICI</span></em></p></div>"},{"i":"5673e891e1dd","n":272,"o":"272-5","u":"Physiopathologie","t":"Connaître l'importance d'Helicobacter pylori (HP) dans la récidive ulcéreuse","q":"Quels sont les points essentiels concernant l'importance d'Helicobacter pylori (HP) dans la récidive ulcéreuse ?","a":"<div class=\"notion-course\"><p><strong><span><span class=\"nc-red_bg\">Helicobacter pylori</span></span></strong> — <span>bacille à Gram négatif flagellé, spiralé</span>, doté d'une <span><span class=\"nc-pink nc-bold\">activité</span> <span class=\"nc-pink nc-bold\">uréasique</span></span> qui lui permet de résister à l'acidité gastrique ; il colonise la <span class=\"nc-purple nc-bold\">muqueuse</span> gastrique.</p>\n      <p><strong>Rôle dans la récidive ulcéreuse</strong> — l'<span>éradication d'HP</span> est ce qui prévient la récidive de l'ulcère. Un <span>UGD</span> associé à HP et <span>non éradiqué récidive de façon quasi constante</span>.</p>\n      <p><strong>Profils sécréteurs et complications</strong> de la <span><span class=\"nc-orange_bg\">gastrite</span></span><span class=\"nc-orange_bg\"> chronique</span> à HP :</p>\n      <table>\n        <thead><tr><th>Profil</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td>Hypersécréteur</td><td><span>Gastrite</span> <span>antrale peu atrophiante</span> → <span><span class=\"nc-blue nc-bold\">hyperchlorhydrie</span></span> → <span><span class=\"nc-red nc-bold\">ulcère duodénal</span></span> (≈ <span>10 %</span>)</td></tr>\n          <tr><td>Hyposécréteur</td><td><span><span class=\"nc-red\">Atrophie</span></span> de la <span class=\"nc-purple nc-bold\">muqueuse</span> → <span><span class=\"nc-blue nc-bold\">achlorhydrie</span></span> → <span><span class=\"nc-red nc-bold\">ulcère gastrique</span></span> (≈ <span>3 %</span>) ; séquence <span class=\"nc-red nc-bold\">métaplasie intestinale</span> (<span>40 %</span>) → <span class=\"nc-red\">dysplasie</span> (<span>8 %</span>) → <span><span class=\"nc-red nc-bold\">adénocarcinome gastrique</span></span> (<span>1-3 %</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans le contexte de l'infection à HP, à <span class=\"nc-blue nc-bold\">prédominance antrale</span>, <span>les</span> <span>ulcères duodénaux sont 3 à 4× plus fréquents</span> que les ulcères gastriques.</p>\n      <div class=\"callout callout-info\"><strong>Pierre angulaire — </strong>l'<span>éradication d'<span class=\"nc-pink_bg\">H. pylori</span></span> est la mesure de prévention de la récidive ulcéreuse.</div></div>"},{"i":"d6bb2eca12ae","n":272,"o":"272-13","u":"Identifier une urgence","t":"Connaître l'examen de première intention devant une contracture abdominale","q":"Quels sont les points essentiels concernant l'examen de première intention devant une contracture abdominale ?","a":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-orange nc-bold\">contracture abdominale</span></span> faisant suspecter une <span class=\"nc-red nc-bold\">perforation</span> d'ulcère :</p>\n      <div class=\"callout callout-danger\"><strong>Examen de 1re intention — </strong><span>TDM abdomino-pelvienne injectée</span> : elle recherche un <span><span class=\"nc-red nc-bold\">pneumopéritoine</span></span> et une <span>réaction inflammatoire</span> de la région antro-pyloro-bulbaire. L'<span>endoscopie est contre-indiquée</span> de façon absolue en cas de <span class=\"nc-red nc-bold\">perforation</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 357 — <span>Péritonite</span> aiguë</em></p></div>"},{"i":"10b20b099d65","n":272,"o":"272-14","u":"Suivi et / ou pronostic","t":"Connaître le risque dégénérescence des ulcères selon leur localisation","q":"Quels sont les points essentiels concernant le risque dégénérescence des ulcères selon leur localisation ?","a":"<div class=\"notion-course\"><p>Le <strong>risque de dégénérescence</strong> dépend strictement de la localisation de l'ulcère :</p>\n      <table>\n        <thead><tr><th>Localisation</th><th>Risque de cancérisation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red nc-bold\">Ulcère duodénal</span></td><td>L'<span class=\"nc-red nc-bold\">ulcère duodénal</span> <span>n'est jamais un cancer et ne se cancérise jamais</span></td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Ulcère gastrique</span></td><td>L'UG et l'<span><span class=\"nc-red nc-bold\">adénocarcinome gastrique</span></span> surviennent tous deux <span class=\"nc-red nc-bold\">sur une </span><span><span class=\"nc-red nc-bold\">muqueuse atrophique</span></span> (<span>condition précancéreuse</span>) ; un <span>cancer débutant</span> peut mimer un UG bénin</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Conséquence pratique — </strong>la découverte d'un <span><span class=\"nc-red nc-bold\">ulcère gastrique</span></span> impose des <span>biopsies des berges</span> (6 à 12) en plus des biopsies de l'<span class=\"nc-red nc-bold\">antre</span> et du fundus, à la recherche d'un <span class=\"nc-red nc-bold\">cancer</span> et de <span>lésions précancéreuses</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac</em></p></div>"},{"i":"0c0bb144e0c2","n":272,"o":"272-17","u":"Définition","t":"Connaître les principaux types de gastrite","q":"Quels sont les points essentiels concernant les principaux types de gastrite ?","a":"<div class=\"notion-course\"><p>La <strong><span>classification</span> de Sydney</strong> repose sur trois caractéristiques principales :</p>\n      <table>\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Étiologie</td><td>La cause de la <span>gastrite</span></td></tr>\n          <tr><td>Topographie</td><td><span>Gastrite</span> <span><span class=\"nc-blue nc-bold\">fundique</span></span> (maladie de Biermer) ou <span><span class=\"nc-blue nc-bold\">antrale</span></span> (<span>H. pylori</span>)</td></tr>\n          <tr><td>Morphologie</td><td>Siège et densité de l'infiltrat <span>inflammatoire</span>, caractère <span>actif</span> (PNN présents) ou inactif, degré d'<span class=\"nc-red\">atrophie</span> muqueuse et de <span class=\"nc-red nc-bold\">métaplasie intestinale</span>, <span class=\"nc-purple_bg\">présence</span> <span class=\"nc-red nc-bold\">d'agents pathogènes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principaux types de <span>gastrite</span> :</strong></p>\n      <table>\n        <thead><tr><th>Type</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>À <span>H. pylori</span></td><td>De loin la <strong>plus fréquente</strong> ; topographie <span>antrale</span></td></tr>\n          <tr><td><span>Auto-immune</span> (Biermer)</td><td>Topographie <span><span class=\"nc-blue nc-bold\">fundique</span></span> ; <span class=\"nc-red_bg\">atrophie progressive des glandes du fundus</span></td></tr>\n          <tr><td>Lymphocytaire</td><td>Association possible à une <span>maladie cœliaque</span>, une <span>colite lymphocytaire</span> ou une <span><span class=\"nc-purple nc-bold\">infection</span> à H. pylori</span></td></tr>\n          <tr><td>À <span class=\"nc-blue_bg nc-bold\">collagène</span></td><td><span>Bande de <span class=\"nc-blue_bg nc-bold\">collagène</span> sous-épithéliale</span> ; rare ; association possible à une <span>colite <span class=\"nc-blue_bg nc-bold\">collagène</span></span> ou une <span>maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span><span class=\"nc-purple nc-bold\">Crohn</span>, <span class=\"nc-purple nc-bold\">sarcoïdose</span>, <span class=\"nc-purple nc-bold\">tuberculose</span>, <span class=\"nc-purple nc-bold\">syphilis</span></span>, parasites</td></tr>\n          <tr><td>À <span>éosinophiles</span></td><td><span><span class=\"nc-red nc-bold\">Allergie alimentaire</span>, <span class=\"nc-red nc-bold\">parasitose</span></span> (anisakiase)</td></tr>\n          <tr><td><span>Virale</span></td><td><span>CMV, HSV</span> ; surtout l'immunodéprimé</td></tr>\n          <tr><td>Phlegmoneuse</td><td><span><span class=\"nc-purple nc-bold\">Infection</span> <span class=\"nc-purple nc-bold\">bactérienne</span></span> sévère de la paroi gastrique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gastropathies</strong> (≠ <span>gastrite</span>, <span class=\"nc-pink nc-bold\">sans infiltrat </span><span><span class=\"nc-pink nc-bold\">inflammatoire</span></span>) : induite par <span>les</span> <span>AINS</span> ; chimique (<span>alcool</span>, <span class=\"nc-brown_bg\">reflux</span> biliaire post-gastrectomie) ; congestive (<span>HTP</span>, ectasies vasculaires antrales) ; hypertrophique (<span class=\"nc-orange_bg\">maladie de Ménétrier</span>) ; radique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span>MICI</span></em></p></div>"},{"i":"5a25b05845c3","n":272,"o":"272-18","u":"Physiopathologie","t":"Connaître les causes de la gastrite","q":"Quels sont les points essentiels concernant les causes de la gastrite ?","a":"<div class=\"notion-course\"><p><strong>Rappel anatomo-fonctionnel</strong> — <span>les</span> glandes gastriques diffèrent selon le type de muqueuse :</p>\n      <table>\n        <thead><tr><th>Glandes</th><th>Cellules &amp; sécrétions</th></tr></thead>\n        <tbody>\n          <tr><td>Fundiques</td><td><span><span class=\"nc-blue_bg\">Cellules pariétales</span></span> (<span class=\"nc-pink nc-bold\">HCl</span> + <span class=\"nc-pink nc-bold\">facteur intrinsèque</span>) ; <span><span class=\"nc-blue_bg\">cellules principales</span></span> (<span class=\"nc-pink nc-bold\">pepsinogène</span>) ; <span><span class=\"nc-blue_bg\">cellules ECL</span></span> (<span class=\"nc-pink nc-bold\">histamine</span>)</td></tr>\n          <tr><td>Antrales</td><td><span class=\"nc-yellow_bg\">Cellules </span><span><span class=\"nc-yellow_bg\">mucosécrétantes</span></span> ; <span class=\"nc-yellow_bg\">cellules endocrines </span><span><span class=\"nc-yellow_bg\">à gastrine</span></span> (stimule l'HCl fundique et <span>les</span> cellules ECL)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes de <span>gastrite</span> :</strong></p>\n      <table>\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span>H. pylori</span></td><td>La <strong>1re cause</strong> ; <span>gastrite</span> <span class=\"nc-blue nc-bold\">antrale</span></td></tr>\n          <tr><td><span>Auto-immune</span> (Biermer)</td><td><span>Gastrite</span> <span><span class=\"nc-blue nc-bold\">fundique</span></span> ; sujet <span>&gt; 50 ans</span>, prédominance <span class=\"nc-brown_bg\">féminine</span> ; l'<span class=\"nc-red\">atrophie</span> <span class=\"nc-blue nc-bold\">fundique</span> entraîne une <span><span class=\"nc-orange_bg\">carence en B12</span></span>, une <span><span class=\"nc-orange_bg\">carence martiale</span></span> et une <span><span class=\"nc-blue nc-bold\">hypergastrinémie réactionnelle</span></span> (risque de TNE à cellules ECL) ; séquence <span class=\"nc-red\">atrophie</span> → <span class=\"nc-red\">métaplasie</span> → <span class=\"nc-red\">dysplasie</span> → <span><span class=\"nc-red nc-bold\">adénocarcinome</span></span></td></tr>\n          <tr><td>Lymphocytaire</td><td>Association à une <span>maladie cœliaque</span></td></tr>\n          <tr><td>À <span class=\"nc-blue_bg nc-bold\">collagène</span></td><td>Rare ; <span>dépôt de <span class=\"nc-blue_bg nc-bold\">collagène</span> sous-épithélial</span> ; à rapprocher de la colite <span class=\"nc-blue_bg nc-bold\">collagène</span> et de la <span>maladie cœliaque</span></td></tr>\n          <tr><td>Granulomateuse</td><td><span><span class=\"nc-purple nc-bold\">Crohn</span>, <span class=\"nc-purple nc-bold\">sarcoïdose</span>, <span class=\"nc-purple nc-bold\">tuberculose</span>, <span class=\"nc-purple nc-bold\">syphilis</span></span>, parasites, mycoses</td></tr>\n          <tr><td>À <span>éosinophiles</span></td><td><span><span class=\"nc-red nc-bold\">Allergie alimentaire</span>, anisakiase</span></td></tr>\n          <tr><td>Associée à Crohn</td><td>Atteinte gastrique chez ≈ <span>30 %</span> des patients atteints de Crohn</td></tr>\n          <tr><td>Infectieuse</td><td><span>Virale</span> (<span><span class=\"nc-purple nc-bold\">CMV</span>, <span class=\"nc-purple nc-bold\">HSV</span></span>), phlegmoneuse (<span><span class=\"nc-purple nc-bold\">bactérienne</span></span>) — surtout l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 282 — <span>MICI</span></em></p></div>"},{"i":"595a4a3c8bf9","n":272,"o":"272-19","u":"Examens complémentaires","t":"Connaître les indications et la place des biopsies pour le diagnostic, le traitement et le suivi","q":"Quels sont les points essentiels concernant les indications et la place des biopsies pour le diagnostic, le traitement et le suivi ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-yellow_bg\">gastrite</span></span> est un diagnostic <strong>histologique</strong> : <span>5 biopsies</span> (<span class=\"nc-blue nc-bold\">2 fundus</span>, <span <span=\"\">&gt;<span class=\"nc-blue nc-bold\">2</span></span><span class=\"nc-blue nc-bold\"> antre</span>, <span class=\"nc-blue nc-bold\">1 angle de la petite courbure</span>). Il n'existe pas de corrélation entre l'aspect <span class=\"nc-blue_bg\">endoscopique</span>, l'<span>histologie</span> et <span>les</span> symptômes.</p>\n      <p><strong>Indications des biopsies</strong> selon l'aspect <span class=\"nc-blue_bg\">endoscopique</span> de la muqueuse :</p>\n      <table>\n        <thead><tr><th>Situation</th><th>Objectif des biopsies</th></tr></thead>\n        <tbody>\n          <tr><td>Présence d'une <span>lésion</span> endoscopique</td><td>Confirmer le diagnostic de <span><span class=\"nc-yellow_bg\">gastrite</span></span> et en déterminer la cause</td></tr>\n          <tr><td>Absence de <span>lésion</span> <span class=\"nc-blue_bg\">endoscopique</span></td><td>Rechercher une pathologie spécifique : <span><span class=\"nc-orange_bg\">carence en B12</span> avec anémie macrocytaire</span> (recherche d'<span class=\"nc-red\">atrophie</span>), ATCD familial de <span class=\"nc-red nc-bold\">cancer gastrique</span>, <span class=\"nc-orange_bg nc-bold\">douleurs</span> abdominales chroniques (recherche d'<span><span class=\"nc-pink_bg\">H. pylori</span></span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"nc-yellow_bg\">Traitement</span></strong> — une fois le diagnostic posé, il est <span>ciblé sur la cause</span> identifiée : éradication d'HP, arrêt de l'<span>alcool</span>, <span class=\"nc-yellow_bg\">traitement</span> de l'<span>hypertension</span> portale…</p>\n      <div class=\"callout callout-danger\"><strong><span>Suivi</span> — </strong>une <span><span class=\"nc-blue nc-bold\">surveillance endoscopique</span> à vie</span> avec <span class=\"nc-red nc-bold\">biopsies</span> est nécessaire pour : la <span><span class=\"nc-yellow_bg\">gastrite</span> auto-immune de Biermer</span> (risque d'<span class=\"nc-red nc-bold\">adénocarcinome</span> et de tumeur neuro-endocrine) ; la <span><span class=\"nc-yellow_bg\">gastrite</span> à risque de dégénérescence</span> séquellaire d'une <span class=\"nc-purple nc-bold\">infection</span> à HP (<span class=\"nc-red\">atrophie</span>, <span class=\"nc-red\">métaplasie</span>, <span class=\"nc-red\">dysplasie</span> = <span>lésions précancéreuses</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 303 — Tumeur estomac · 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La surveillance d’une <span class=\"nc-red\">atrophie</span> ou <span class=\"nc-red\">métaplasie</span> gastrique dépend de l’étendue, de l’histologie, des facteurs de risque et de l’âge ; elle n’est pas systématiquement annuelle ou à vie pour toute <span class=\"nc-yellow_bg\">gastrite</span>.</li></ul></div></div>"},{"i":"8d3e7510a4ea","n":272,"o":"272-20","u":"Prise en charge","t":"Connaître les principes du traitement de la gastrite","q":"Quels sont les points essentiels concernant les principes du traitement de la gastrite ?","a":"<div class=\"notion-course\"><p>Le traitement d'une <span>gastrite</span> consiste à <strong>traiter la cause</strong> identifiée :</p>\n      <table>\n        <thead><tr><th>Cause</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span>Gastrite</span> à H. pylori</td><td><span>Éradication d'H. pylori</span></td></tr>\n          <tr><td>Biermer (<span>auto-immune</span>)</td><td>Biermer : supplémentation durable en vitamine B12, classiquement parentérale ; voie orale à forte dose envisageable dans des situations sélectionnées avec suivi adapté. Corriger une <span class=\"nc-orange_bg\">carence martiale</span> associée. <span class=\"nc-blue nc-bold\">Surveillance endoscopique</span> selon <span class=\"nc-yellow_bg\">gastrite</span> atrophique, lésions et terrain ; le seuil de soixante-dix ans n’est pas une règle universelle d’arrêt.</td></tr>\n          <tr><td>Gastropathie chimique</td><td><span>Arrêt de l'alcool</span> ou de la cause</td></tr>\n          <tr><td>Gastropathie d'<span>HTP</span></td><td>Traitement de l'<span>hypertension portale</span></td></tr>\n          <tr><td>Causes spécifiques</td><td>Traitement étiologique (<span><span class=\"nc-purple_bg nc-bold\">CMV</span></span>, <span>Crohn</span>…)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li><span class=\"nc-orange nc-bold\">Carence</span> en vitamine B12 : correction indispensable, voie parentérale ou orale à forte dose selon gravité, cause et suivi. Une atteinte neurologique ou une situation sévère impose une prise en charge rapide adaptée.</li></ul></div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d941819da300cf3e83a15425?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
